css:
/* Glow Aura — styles.css
 * Glass UI over a wallpaper. Colours come from CSS variables written by
 * theme.js (see #themeVars). UXP-safe: flexbox only, no gap, no grid,
 * no backdrop-filter, no box-shadow; glass = translucent fills + hairlines.
 */

:root {
  --text: #fff3ea;
  --text-2: rgba(255, 243, 234, 0.72);
  --text-3: rgba(255, 243, 234, 0.48);
  --text-4: rgba(255, 243, 234, 0.28);
  --accent: #ff7a33;
  --accent-soft: rgba(255, 122, 51, 0.22);
  --accent-line: rgba(255, 122, 51, 0.65);
  --on-accent: #ffffff;
  --glass: rgba(27, 9, 5, 0.45);
  --glass-2: rgba(27, 9, 5, 0.59);
  --glass-3: rgba(27, 9, 5, 0.75);
  --fill: rgba(255, 243, 234, 0.13);
  --fill-2: rgba(255, 243, 234, 0.2);
  --stroke: rgba(255, 243, 234, 0.14);
  --stroke-2: rgba(255, 243, 234, 0.26);
  --dot: rgba(255, 243, 234, 0.32);
  --dim: rgba(0, 0, 0, 0.3);
  --base: #120806;
  --primary-bg: #ffffff;
  --primary-fg: #1e120d;
  --danger: #ff6b6b;
  --success: #6ee7a8;
  --r-card: 14px;
  --r-pill: 17px;
  --r-btn: 18px;
  --fs: 12px;
  --fs-sm: 11px;
  --fs-lg: 14px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  width: 100%;
  overflow: hidden;
  background-color: var(--base);
  color: var(--text);
  font-size: var(--fs);
  font-family: "Adobe Clean", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

#gaRoot {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}

/* ---------- wallpaper ---------- */

.bg {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  overflow: hidden;
}

.bg img {
  position: absolute;
}

.bg .dim {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  background-color: var(--dim);
}

/* ---------- shell ---------- */

.app {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
}

.top {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding: 10px 10px 8px 14px;
  flex-shrink: 0;
}

.top .brand-logo {
  width: 20px;
  height: 20px;
  margin-right: 8px;
  flex-shrink: 0;
}

.top .brand {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  min-width: 0;
}

.top .brand-name {
  font-size: var(--fs-lg);
  font-weight: 700;
  letter-spacing: 0.2px;
  white-space: nowrap;
}

.top .brand-sub {
  font-size: var(--fs-sm);
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scroll {
  flex-grow: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 2px 10px 12px 10px;
}

.spacer {
  flex-grow: 1;
}

.ic {
  display: flex;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* ---------- hero (home) ---------- */

.hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 0 12px 0;
}

.hero img {
  width: 92px;
  height: 92px;
}

.hero .hero-title {
  font-size: 20px;
  font-weight: 700;
  margin-top: 2px;
  letter-spacing: 0.3px;
}

.hero .hero-sub {
  color: var(--text-2);
  font-size: var(--fs-sm);
  margin-top: 4px;
  text-align: center;
}

.chip {
  display: flex;
  flex-direction: row;
  align-items: center;
  align-self: center;
  margin-top: 10px;
  padding: 5px 12px;
  border-radius: 14px;
  background-color: var(--glass);
  border: 1px solid var(--stroke);
  color: var(--text-2);
  font-size: var(--fs-sm);
  max-width: 100%;
}

.chip .dot {
  width: 6px;
  height: 6px;
  border-radius: 3px;
  background-color: var(--success);
  margin-right: 8px;
  flex-shrink: 0;
}

.chip.is-warn .dot {
  background-color: var(--accent);
}

.chip .chip-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---------- cards ---------- */

.card {
  transition: opacity 200ms ease;
  background-color: var(--glass);
  border: 1px solid var(--stroke);
  border-radius: var(--r-card);
  padding: 10px 12px 12px 12px;
  margin-bottom: 10px;
}

.card-head {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 22px;
  margin-bottom: 6px;
}

.card-ic {
  display: flex;
  width: 16px;
  height: 16px;
  margin-right: 8px;
}

.card-title {
  font-weight: 700;
  font-size: var(--fs-sm);
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text);
}

.card-body {
  transition: opacity 200ms ease;
}

.card.is-off .card-body {
  opacity: 0.38;
}

#view {
  transition: opacity 160ms ease;
}

#view.is-entering {
  opacity: 0;
}

.item,
.look,
.sw,
.theme-card {
  transition: background-color 160ms ease, border-color 160ms ease;
}

.hint {
  margin: 0 0 8px 0;
  color: var(--text-3);
  font-size: var(--fs-sm);
  line-height: 15px;
}

/* ---------- pill slider ---------- */

.pill {
  position: relative;
  height: 34px;
  border-radius: var(--r-pill);
  background-color: var(--glass-2);
  border: 1px solid var(--stroke);
  margin-top: 6px;
  overflow: hidden;
  cursor: pointer;
  outline: none;
}

.pill:focus,
.pill.is-dragging {
  border-color: var(--accent-line);
}

.pill-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: var(--r-pill);
  background-color: var(--fill-2);
  border-right: 1px solid var(--stroke-2);
  min-width: 0;
}

.pill-handle {
  position: absolute;
  right: 8px;
  top: 10px;
  width: 2px;
  height: 12px;
  border-radius: 1px;
  background-color: var(--text);
}

.pill-dots {
  position: absolute;
  left: 0;
  right: 0;
  top: 15px;
  height: 3px;
}

.pill-dot {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 2px;
  background-color: var(--dot);
}

.pill-label {
  position: absolute;
  left: 12px;
  top: 9px;
  color: var(--text);
  white-space: nowrap;
  font-size: var(--fs);
}

.pill-value {
  position: absolute;
  right: 12px;
  top: 9px;
  color: var(--text);
  font-weight: 600;
  white-space: nowrap;
  font-size: var(--fs);
}

.pill-input {
  width: 64px;
  height: 22px;
  margin-top: -4px;
  font-size: var(--fs);
  text-align: right;
}

.pill-hue {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 4px;
  height: 3px;
  width: auto;
  border-radius: 2px;
  opacity: 0.9;
}

/* ---------- rows, switch, segmented ---------- */

.row {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 30px;
  margin-top: 4px;
}

.row-label {
  flex-grow: 1;
  color: var(--text-2);
  margin-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.switch {
  transition: background-color 180ms ease, border-color 180ms ease;
  position: relative;
  width: 34px;
  height: 20px;
  border-radius: 10px;
  background-color: var(--fill-2);
  border: 1px solid var(--stroke-2);
  flex-shrink: 0;
  cursor: pointer;
  outline: none;
}

.switch .knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 7px;
  background-color: var(--text);
  transition: left 180ms ease, background-color 180ms ease;
}

.switch.is-on {
  background-color: var(--accent);
  border-color: var(--accent);
}

.switch.is-on .knob {
  left: 16px;
  background-color: var(--on-accent);
}

.segmented {
  position: relative;
  display: flex;
  flex-direction: row;
  padding: 3px;
  border-radius: var(--r-pill);
  background-color: var(--glass-2);
  border: 1px solid var(--stroke);
}

.segmented.compact {
  flex-shrink: 0;
}

.seg {
  flex-grow: 1;
  flex-basis: 0;
  min-width: 0;
  overflow: hidden;
  border: 1px solid transparent;
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  height: 26px;
  padding: 0 10px;
  border-radius: 13px;
  color: var(--text-2);
  cursor: pointer;
  white-space: nowrap;
  outline: none;
}

.segmented.compact .seg {
  flex-grow: 0;
  flex-basis: auto;
  height: 22px;
  padding: 0 9px;
  border-radius: 11px;
  font-size: var(--fs-sm);
}

.seg.has-ic .ic {
  margin-right: 5px;
}

.seg:hover {
  color: var(--text);
}

.seg.is-active {
  background-color: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
  font-weight: 600;
}

.seg-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* tabs: inactive = icon only, active = icon + label (never overflows) */
.segmented.tabs {
  margin: 0 0 10px 0;
}

.segmented.tabs .seg {
  flex-grow: 0;
  flex-basis: auto;
  padding: 0 7px;
}

.segmented.tabs .seg.is-active {
  flex-grow: 1;
  padding: 0 12px;
}

.segmented.tabs .seg .ic {
  margin-right: 0;
}

.segmented.tabs .seg.is-active .ic {
  margin-right: 6px;
}

/* ---------- buttons ---------- */

.btn {
  transition: background-color 160ms ease, opacity 160ms ease, border-color 160ms ease;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border-radius: var(--r-btn);
  cursor: pointer;
  white-space: nowrap;
  outline: none;
  flex-shrink: 0;
  font-weight: 600;
  border: 1px solid transparent;
}

.btn .ic {
  margin-right: 6px;
}

.btn.icon-only {
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 16px;
}

.btn.icon-only .ic {
  margin-right: 0;
}

.btn.btn-sm {
  height: 28px;
  padding: 0 12px;
  border-radius: 14px;
  font-size: var(--fs-sm);
}

.btn.primary {
  background-color: var(--primary-bg);
  color: var(--primary-fg);
}

.btn.primary:hover {
  opacity: 0.9;
}

.btn.glass {
  background-color: var(--glass-2);
  border-color: var(--stroke-2);
  color: var(--text);
}

.btn.glass:hover {
  background-color: var(--glass-3);
}

.btn.ghost {
  background-color: transparent;
  color: var(--text-2);
}

.btn.ghost:hover {
  background-color: var(--fill);
  color: var(--text);
}

.btn.accent {
  background-color: var(--accent);
  color: var(--on-accent);
}

.btn.danger:hover {
  border-color: var(--danger);
}

.btn.is-disabled,
.tool.is-disabled {
  opacity: 0.35;
  cursor: default;
}

.btn:focus,
.tool:focus {
  border-color: var(--accent-line);
}

.btn-row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-top: 8px;
}

.btn-row .btn {
  margin-right: 8px;
  margin-bottom: 6px;
}

.btn-stack .btn {
  margin-top: 8px;
}

/* ---------- lists ---------- */

.list {
  border-radius: var(--r-card);
  border: 1px solid var(--stroke);
  overflow: hidden;
}

.item {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 36px;
  padding: 0 6px 0 12px;
  border-bottom: 1px solid var(--stroke);
  cursor: pointer;
  outline: none;
  background-color: var(--glass-2);
}

.item:last-child {
  border-bottom-width: 0;
}

.item:hover,
.item:focus {
  background-color: var(--glass-3);
}

.item.is-active {
  background-color: var(--accent-soft);
}

.item .item-ic {
  display: flex;
  width: 16px;
  height: 16px;
  margin-right: 10px;
  flex-shrink: 0;
}

.item .item-name {
  flex-grow: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item .item-meta {
  color: var(--text-3);
  font-size: var(--fs-sm);
  margin-left: 8px;
}

.item .btn.icon-only {
  width: 26px;
  height: 26px;
  border-radius: 13px;
}

.item input.rename {
  flex-grow: 1;
  height: 24px;
}

.looks {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-right: -6px;
}

.look {
  display: flex;
  flex-direction: row;
  align-items: center;
  height: 30px;
  padding: 0 12px;
  margin: 0 6px 6px 0;
  border-radius: 15px;
  background-color: var(--glass-2);
  border: 1px solid var(--stroke);
  cursor: pointer;
  white-space: nowrap;
  font-size: var(--fs-sm);
}

.look:hover {
  border-color: var(--accent-line);
}

.look .ic {
  margin-right: 6px;
  width: 14px;
  height: 14px;
}

.inline {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.inline input {
  flex-grow: 1;
  min-width: 0;
  height: 32px;
  margin-right: 8px;
  font-size: var(--fs);
}

/* ---------- swatches / themes ---------- */

.swatches {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  margin-top: 6px;
}

.sw {
  width: 22px;
  height: 22px;
  border-radius: 11px;
  margin: 0 8px 8px 0;
  border: 2px solid var(--stroke-2);
  cursor: pointer;
}

.sw.is-active {
  border-color: var(--text);
}

.themes {
  display: flex;
  flex-direction: row;
}

.theme-card {
  flex-grow: 1;
  flex-basis: 0;
  margin-right: 8px;
  border-radius: var(--r-card);
  border: 2px solid var(--stroke);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  height: 118px;
}

.theme-card:last-child {
  margin-right: 0;
}

.theme-card img {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
}

.theme-card .theme-name {
  position: absolute;
  left: 6px;
  right: 6px;
  bottom: 6px;
  height: 22px;
  border-radius: 11px;
  background-color: rgba(0, 0, 0, 0.45);
  color: #ffffff;
  font-size: var(--fs-sm);
  font-weight: 600;
  text-align: center;
  padding-top: 4px;
}

.theme-card.is-active {
  border-color: var(--accent);
}

/* ---------- dock ---------- */

.dock {
  flex-shrink: 0;
  margin: 0 10px 10px 10px;
  padding: 10px;
  border-radius: var(--r-card);
  background-color: var(--glass-3);
  border: 1px solid var(--stroke);
}

.dock-row {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.dock-row + .dock-row {
  margin-top: 10px;
}

.status {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-grow: 1;
  min-width: 0;
  color: var(--text-3);
  font-size: var(--fs-sm);
}

.status .led {
  width: 7px;
  height: 7px;
  border-radius: 4px;
  background-color: var(--success);
  margin-right: 7px;
  flex-shrink: 0;
}

.status.is-busy .led {
  background-color: var(--accent);
}

.status.is-error .led {
  background-color: var(--danger);
}

.status .status-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tools {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
}

.tool {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-grow: 1;
  flex-basis: 0;
  cursor: pointer;
  outline: none;
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 2px 0;
}

.tool-ic {
  transition: background-color 180ms ease, border-color 180ms ease;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 16px;
  background-color: var(--glass-2);
  border: 1px solid var(--stroke-2);
}

.tool-label {
  margin-top: 3px;
  font-size: 10px;
  color: var(--text-3);
  white-space: nowrap;
}

.tool.is-on .tool-ic {
  background-color: var(--accent);
  border-color: var(--accent);
}

.tool.is-on .tool-label {
  color: var(--text);
}

.actions {
  display: flex;
  flex-direction: row;
}

.actions .btn.glass {
  flex-grow: 1;
  flex-basis: 0;
  margin-right: 8px;
}

.actions .btn.primary {
  flex-grow: 2;
  flex-basis: 0;
}

/* ---------- editor header ---------- */

.subhead {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin: 0 0 10px 0;
}

.subhead .sub-text {
  flex-grow: 1;
  min-width: 0;
  margin-left: 8px;
}

.subhead .sub-title {
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.subhead .sub-meta {
  color: var(--text-3);
  font-size: var(--fs-sm);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---------- misc ---------- */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 8px;
  text-align: center;
}

.empty-ic {
  display: flex;
  width: 22px;
  height: 22px;
  margin-bottom: 6px;
}

.empty-title {
  font-weight: 600;
  margin-bottom: 3px;
}

.empty-text {
  color: var(--text-3);
  font-size: var(--fs-sm);
  line-height: 15px;
}

.toast {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 16px;
  padding: 10px 14px;
  border-radius: var(--r-card);
  background-color: var(--glass-3);
  border: 1px solid var(--stroke-2);
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: 16px;
  display: none;
}

.toast.is-visible {
  display: block;
}

body.has-dock .toast {
  bottom: 168px;
}

.toast.success {
  border-color: var(--success);
}

.toast.error {
  border-color: var(--danger);
}

.toast.warning {
  border-color: var(--accent);
}

.about {
  color: var(--text-3);
  font-size: var(--fs-sm);
  line-height: 16px;
  padding: 4px 0 8px 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
}
.about-wa {
  display: flex;
  flex-direction: row;
  align-items: center;
  cursor: pointer;
  padding: 2px 8px 2px 3px;
  border-radius: 999px;
  border: 1px solid var(--stroke);
  background-color: var(--glass);
  transition: opacity 160ms ease;
}
.about-wa:hover {
  opacity: 0.8;
}
.about-wa .wa-icon {
  width: 18px;
  height: 18px;
  margin-right: 6px;
}
.about-wa .wa-num {
  color: var(--text);
  font-weight: 600;
}

.blocker {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  background-color: var(--dim);
}

.blocker.is-visible {
  display: flex;
}

.blocker img {
  width: 72px;
  height: 72px;
  margin-bottom: 12px;
}

.blocker h2 {
  margin: 0 0 8px 0;
  font-size: 15px;
}

.blocker p {
  margin: 0;
  color: var(--text-2);
  line-height: 18px;
}

/* ---------- credit ---------- */

.credit {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: row;
  align-items: center;
  margin: 6px 0 4px 0;
  padding: 8px 10px;
  border-radius: var(--r-card);
  background-color: var(--glass);
  border: 1px solid var(--stroke);
}

.credit .avatar {
  width: 34px;
  height: 34px;
  border-radius: 17px;
  flex-shrink: 0;
}

.credit-text {
  flex-grow: 1;
  min-width: 0;
  margin-left: 10px;
}

.credit-by {
  font-size: 10px;
  color: var(--text-3);
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.credit-name {
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.credit-social {
  display: flex;
  flex-direction: row;
  flex-shrink: 0;
}

.credit .social {
  width: 24px;
  height: 24px;
  border-radius: 12px;
  margin-left: 8px;
  cursor: pointer;
  transition: opacity 160ms ease;
}

.credit .social:hover {
  opacity: 0.8;
}

/* sliding pill for tab bars */
.segmented.tabs {
  position: relative;
}

.seg-thumb {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: 0;
  border-radius: 13px;
  background-color: var(--accent);
}

.segmented.has-thumb .seg {
  position: relative;
  flex-grow: 0;
  flex-shrink: 0;
  flex-basis: auto;
  padding: 0;
  justify-content: center;
}

.segmented.has-thumb .seg.is-active {
  background-color: transparent;
  border-color: transparent;
}

.segmented.has-thumb .seg.is-active .ic {
  margin-right: 6px;
}

/* Bangla interface: system Bengali fonts (Windows: Nirmala UI, macOS: Kohinoor Bangla) */
body.lang-bn {
  font-family: "Nirmala UI", "Kohinoor Bangla", "Bangla Sangam MN", "Hind Siliguri", "Noto Sans Bengali", "Vrinda", "Adobe Clean", "Segoe UI", sans-serif;
}

/* plain segmented rows: sliding pill with the white label inside it */
.seg-pill {
  position: absolute;
  top: 3px;
  height: 26px;
  left: 0;
  width: 0;
  overflow: hidden;
  border-radius: 13px;
  background-color: var(--accent);
  pointer-events: none;
}
.seg-ghosts {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 4000px;
}
.seg-ghost {
  position: absolute;
  top: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  color: var(--on-accent);
  font-weight: 600;
  white-space: nowrap;
}
.segmented.compact .seg-ghost {
  font-size: var(--fs-sm);
}
.seg-ghost.has-ic .ic {
  margin-right: 5px;
}
.segmented.slide-ready .seg.is-active {
  background-color: transparent;
  border-color: transparent;
  color: var(--text-2);
}

/* credit card light: sweep band + glow rings */
.credit .sweep {
  position: absolute;
  top: -20px;
  left: -90px;
  width: 70px;
  height: 100px;
  pointer-events: none;
}
.glow-wrap {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-shrink: 0;
}
.glow-ring {
  position: absolute;
  width: 46px;
  height: 46px;
  left: -3px;
  top: -11px;
  pointer-events: none;
}
.glow-wrap.is-avatar .glow-ring {
  width: 60px;
  height: 60px;
  left: -13px;
  top: -13px;
}

/* update banner */
.update-card {
  margin: 0 0 10px 0;
  padding: 10px 12px;
  border-radius: var(--r-card);
  background-color: var(--glass);
  border: 1px solid var(--accent);
}
.update-title {
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 4px;
}
.update-notes {
  color: var(--text-2);
  font-size: var(--fs-sm);
  line-height: 16px;
  margin-bottom: 8px;
}

/* update pop-up (always on top, every screen) */
.update-notice {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 58px;
  display: none;
  flex-direction: row;
  align-items: center;
  padding: 10px 10px 10px 14px;
  border-radius: var(--r-card);
  background-color: var(--base);
  border: 1px solid var(--accent);
  z-index: 50;
}
.update-notice.is-visible {
  display: flex;
}
.un-text {
  flex-grow: 1;
  min-width: 0;
  margin-right: 10px;
}
.un-title {
  font-weight: 700;
  color: var(--text);
}
.un-sub {
  font-size: var(--fs-sm);
  color: var(--text-2);
  line-height: 15px;
}
.un-close {
  width: 22px;
  height: 22px;
  margin-left: 6px;
  text-align: center;
  line-height: 20px;
  font-size: 16px;
  color: var(--text-2);
  cursor: pointer;
}

/* ---------- license ---------- */

.lic-input {
  display: block;
  width: 100%;
  height: 34px;
  margin: 0 0 10px 0;
  font-size: 14px;
}

.lic-input.lic-key {
  height: 38px;
  font-size: 15px;
  letter-spacing: 1px;
  text-align: center;
}

.lic-label {
  margin: 0 0 4px 0;
  color: var(--text-2);
  font-size: var(--fs-sm);
  font-weight: 600;
}

.lic-note {
  margin: -6px 0 10px 0;
  color: var(--text-3);
  font-size: 11px;
  line-height: 14px;
}

.lic-saved {
  margin: 0 0 10px 0;
  padding: 7px 10px;
  border-radius: 10px;
  border: 1px solid var(--success);
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: 16px;
}

.lic-msg {
  margin: 0 0 10px 0;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--danger);
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: 16px;
}

.lic-name {
  margin: 0 0 4px 0;
  color: var(--text);
  font-size: var(--fs);
  font-weight: 700;
}

.hint.is-warn {
  color: var(--danger);
}

.card-body > .btn:not(:last-child) {
  margin-bottom: 8px;
}

.lic-pc {
  display: flex;
  align-items: center;
  margin: 0 0 8px 0;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--glass-2);
  border: 1px solid var(--stroke);
}

.lic-pc-info {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  margin-right: 8px;
  min-width: 0;
}

.lic-pc-info b {
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: 16px;
}

.lic-pc-info span {
  color: var(--text-3);
  font-size: var(--fs-sm);
  line-height: 15px;
}

