/*
 * Glow Aura — utils.js
 * Settings schema (single source of truth), validation and small helpers.
 * Pure: no Photoshop dependency, unit-tested in Node.
 */
(function (root, factory) {
  if (root.GlowAura && root.GlowAura.__skipInstalled) return; // a live update is running instead
  "use strict";
  const api = factory();
  root.GlowAura = root.GlowAura || {};
  root.GlowAura.utils = api;
  if (typeof module === "object" && module && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const SETTINGS_VERSION = 3;
  // v3: Exposure reads like Oniric (0 = neutral look); older settings were 1.7 stops higher.
  const EXPOSURE_SHIFT_V3 = 1.7;

  /*
   * Every setting lives here. type: num | enum | bool | int | str.
   * num: min, max, step, def, unit. enum: values, def. bool: def.
   */
  const SCHEMA = {
    "source.mode": { type: "enum", values: ["image", "layer", "outlines", "selection", "brush"], def: "image" },
    "source.layerId": { type: "id", def: null },
    "source.layerName": { type: "str", def: "" },
    "source.outline": { type: "num", min: 1, max: 200, step: 1, def: 12, unit: "px" },

    "input.highlights": { type: "enum", values: ["preserve", "flatten"], def: "preserve" },
    "input.transition": { type: "enum", values: ["soft", "precise"], def: "soft" },
    "input.threshold": { type: "num", min: 0, max: 1, step: 0.01, def: 0.5, unit: "" },
    "input.compression": { type: "num", min: 0, max: 100, step: 1, def: 30, unit: "" },

    "main.opacity": { type: "num", min: 0, max: 200, step: 1, def: 100, unit: "%" },
    "main.core": { type: "num", min: 0, max: 200, step: 1, def: 200, unit: "%" },
    "main.iterations": { type: "num", min: 1, max: 12, step: 1, def: 11, unit: "" },
    "main.radius": { type: "num", min: 2, max: 3000, step: 1, def: 1000, unit: "px" },
    "main.exposure": { type: "num", min: -5, max: 5, step: 0.01, def: -0.5, unit: "" },
    "main.gamma": { type: "num", min: 0.2, max: 3, step: 0.05, def: 1.2, unit: "" },

    "shape.aspect": { type: "num", min: 0.25, max: 6, step: 0.05, def: 1, unit: "" },
    "shape.rotation": { type: "num", min: -90, max: 90, step: 1, def: 0, unit: "°" },

    "streaks.enabled": { type: "bool", def: false },
    "streaks.count": { type: "num", min: 2, max: 8, step: 2, def: 4, unit: "" },
    "streaks.angle": { type: "num", min: -90, max: 90, step: 1, def: 0, unit: "°" },
    "streaks.length": { type: "num", min: 20, max: 4000, step: 1, def: 900, unit: "px" },
    "streaks.intensity": { type: "num", min: 0, max: 300, step: 1, def: 60, unit: "%" },
    "streaks.threshold": { type: "num", min: 0, max: 1, step: 0.01, def: 0.75, unit: "" },

    "aberration.enabled": { type: "bool", def: false },
    "aberration.type": { type: "enum", values: ["offset", "radial"], def: "offset" },
    "aberration.channels": { type: "enum", values: ["rb", "rg", "gb"], def: "rb" },
    "aberration.distance": { type: "num", min: 0, max: 300, step: 1, def: 20, unit: "px" },
    "aberration.blur": { type: "num", min: 0, max: 100, step: 1, def: 6, unit: "px" },
    "aberration.rotation": { type: "num", min: -180, max: 180, step: 1, def: 0, unit: "°" },
    "aberration.intensity": { type: "num", min: 0, max: 100, step: 1, def: 70, unit: "%" },

    "rays.enabled": { type: "bool", def: false },
    "rays.x": { type: "num", min: 0, max: 100, step: 1, def: 50, unit: "%" },
    "rays.y": { type: "num", min: 0, max: 100, step: 1, def: 35, unit: "%" },
    "rays.samples": { type: "num", min: 8, max: 128, step: 1, def: 48, unit: "" },
    "rays.spacing": { type: "num", min: 0.05, max: 1, step: 0.01, def: 0.6, unit: "" },
    "rays.falloff": { type: "num", min: 0.8, max: 1, step: 0.005, def: 0.965, unit: "" },
    "rays.intensity": { type: "num", min: 0, max: 300, step: 1, def: 70, unit: "%" },

    "color.hue": { type: "num", min: -180, max: 180, step: 1, def: 0, unit: "°" },
    "color.saturation": { type: "num", min: 0, max: 200, step: 1, def: 100, unit: "%" },
    "color.colorize": { type: "bool", def: false },

    "output.blend": { type: "enum", values: ["screen", "add"], def: "screen" },
    "output.opacity": { type: "num", min: 0, max: 100, step: 1, def: 100, unit: "%" },
    "mask.enabled": { type: "bool", def: false }
  };

  /** Back-compat alias used by sliders. */
  const RANGES = {};
  Object.keys(SCHEMA).forEach(function (k) {
    if (SCHEMA[k].type === "num") RANGES[k] = SCHEMA[k];
  });

  /** Looks are authored for this long side; distances scale to the document. */
  const REF_SIDE = 5400;
  const DISTANCE_PATHS = ["main.radius", "streaks.length", "aberration.distance", "aberration.blur", "source.outline"];

  /** Scales a look's pixel distances from REF_SIDE to a document's long side. */
  function scaleLookToDoc(settings, longSide) {
    const s = sanitizeSettings(settings);
    if (!longSide || longSide <= 0) return s;
    const k = longSide / REF_SIDE;
    DISTANCE_PATHS.forEach(function (p) {
      setPath(s, p, sanitizeValue(p, getPath(s, p) * k));
    });
    return s;
  }

  /** Groups that presets store (the look, not the source/mask). */
  const LOOK_GROUPS = ["input", "main", "shape", "streaks", "aberration", "rays", "color", "output"];

  function isObj(v) {
    return v !== null && typeof v === "object" && !Array.isArray(v);
  }

  function deepClone(v) {
    return JSON.parse(JSON.stringify(v));
  }

  function clamp(v, min, max) {
    return Math.min(max, Math.max(min, v));
  }

  function decimalsOf(step) {
    return (String(step).split(".")[1] || "").length;
  }

  function roundToStep(v, step, min) {
    const base = typeof min === "number" ? min : 0;
    const n = Math.round((v - base) / step) * step + base;
    return Number(n.toFixed(decimalsOf(step)));
  }

  function toNumber(v, fallback) {
    const n = typeof v === "number" ? v : parseFloat(String(v).replace(",", "."));
    return Number.isFinite(n) ? n : fallback;
  }

  function getPath(obj, path) {
    return path.split(".").reduce(function (o, k) {
      return o == null ? undefined : o[k];
    }, obj);
  }

  function setPath(obj, path, value) {
    const keys = path.split(".");
    const last = keys.pop();
    const target = keys.reduce(function (o, k) {
      if (!isObj(o[k])) o[k] = {};
      return o[k];
    }, obj);
    target[last] = value;
    return obj;
  }

  function sanitizeValue(path, value) {
    const s = SCHEMA[path];
    if (!s) return value;
    switch (s.type) {
      case "num":
        return roundToStep(clamp(toNumber(value, s.def), s.min, s.max), s.step, s.min);
      case "enum":
        return s.values.indexOf(value) >= 0 ? value : s.def;
      case "bool":
        return typeof value === "boolean" ? value : s.def;
      case "id":
        return Number.isInteger(value) && value > 0 ? value : null;
      case "str":
        return typeof value === "string" ? value.slice(0, 255) : s.def;
      default:
        return s.def;
    }
  }

  /** Legacy alias. */
  function sanitizeNumber(path, value) {
    return sanitizeValue(path, value);
  }

  function defaults() {
    const out = { version: SETTINGS_VERSION };
    Object.keys(SCHEMA).forEach(function (k) {
      setPath(out, k, SCHEMA[k].def);
    });
    return out;
  }

  const DEFAULT_SETTINGS = Object.freeze(defaults());

  /**
   * Accepts anything and returns a complete, valid settings object. Never throws.
   * Streak counts are forced even.
   */
  function sanitizeSettings(input) {
    const src = isObj(input) ? input : {};
    const out = { version: SETTINGS_VERSION };
    Object.keys(SCHEMA).forEach(function (k) {
      setPath(out, k, sanitizeValue(k, getPath(src, k)));
    });
    if (out.streaks.count % 2) out.streaks.count = clamp(out.streaks.count + 1, 2, 8);
    // Settings saved before v3 used the old exposure scale.
    if (typeof src.version === "number" && src.version < 3 && isObj(src.main) && typeof src.main.exposure === "number") {
      out.main.exposure = sanitizeValue("main.exposure", src.main.exposure - EXPOSURE_SHIFT_V3);
    }
    return out;
  }

  /** Look-only part (what presets store). */
  function lookPart(settings) {
    const s = sanitizeSettings(settings);
    const out = { version: SETTINGS_VERSION };
    LOOK_GROUPS.forEach(function (g) {
      out[g] = s[g];
    });
    return out;
  }

  /** Merge a look onto existing settings (keeps source + mask). */
  function applyLook(settings, look) {
    const s = sanitizeSettings(settings);
    const l = isObj(look) ? look : {};
    const merged = deepClone(s);
    LOOK_GROUPS.forEach(function (g) {
      if (isObj(l[g])) merged[g] = Object.assign({}, merged[g], l[g]);
    });
    return sanitizeSettings(merged);
  }

  function settingsEqual(a, b) {
    return JSON.stringify(sanitizeSettings(a)) === JSON.stringify(sanitizeSettings(b));
  }

  const HEX_RE = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i;

  function isHex(s) {
    return typeof s === "string" && HEX_RE.test(s.trim());
  }

  function normalizeHex(s, fallback) {
    if (!isHex(s)) return fallback;
    let h = s.trim().replace("#", "").toUpperCase();
    if (h.length === 3) h = h.split("").map((c) => c + c).join("");
    return "#" + h;
  }

  function hexToRgb(hex) {
    const h = normalizeHex(hex, "#FFFFFF").slice(1);
    return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
  }

  function rgbToHex(r, g, b) {
    const p = (n) => clamp(Math.round(toNumber(n, 0)), 0, 255).toString(16).padStart(2, "0");
    return ("#" + p(r) + p(g) + p(b)).toUpperCase();
  }

  function rgba(hex, a) {
    const c = hexToRgb(hex);
    return "rgba(" + c.r + ", " + c.g + ", " + c.b + ", " + clamp(toNumber(a, 1), 0, 1) + ")";
  }

  /** Hue in degrees (0..360) of a hex colour; null for greys. */
  function hexToHue(hex) {
    const c = hexToRgb(hex);
    const r = c.r / 255;
    const g = c.g / 255;
    const b = c.b / 255;
    const mx = Math.max(r, g, b);
    const mn = Math.min(r, g, b);
    const d = mx - mn;
    if (d < 1e-6) return null;
    let h;
    if (mx === r) h = ((g - b) / d) % 6;
    else if (mx === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    return h < 0 ? h + 360 : h;
  }

  function debounce(fn, wait) {
    let t = null;
    const d = function () {
      const args = arguments;
      const self = this;
      if (t) clearTimeout(t);
      t = setTimeout(function () {
        t = null;
        fn.apply(self, args);
      }, wait);
    };
    d.cancel = function () {
      if (t) clearTimeout(t);
      t = null;
    };
    d.pending = function () {
      return t !== null;
    };
    return d;
  }

  function uid(len) {
    const n = len || 6;
    const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    let out = "";
    for (let i = 0; i < n; i++) out += chars[Math.floor(Math.random() * chars.length)];
    return out;
  }

  function versionAtLeast(version, min) {
    const a = String(version || "0").split(".").map((x) => parseInt(x, 10) || 0);
    const b = String(min).split(".").map((x) => parseInt(x, 10) || 0);
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
      const x = a[i] || 0;
      const y = b[i] || 0;
      if (x > y) return true;
      if (x < y) return false;
    }
    return true;
  }

  function formatValue(path, v) {
    const s = SCHEMA[path];
    if (!s || s.type !== "num") return String(v);
    return Number(v).toFixed(decimalsOf(s.step));
  }

  function friendlyError(err) {
    const msg = err ? String((err && err.message) || err) : "";
    if (/^GA:/.test(msg)) return msg.replace(/^GA:\s*/, "");
    if (/modal|executeAsModal|busy/i.test(msg)) {
      return "Photoshop is busy. Close any open dialog or finish the current tool, then try again.";
    }
    if (/not (currently )?available/i.test(msg)) {
      return "That command isn't available right now. Check the active layer and try again.";
    }
    if (/user cancel/i.test(msg)) return "Cancelled.";
    if (/lock/i.test(msg)) return "A layer or its group is locked. Unlock it and try again.";
    if (/memory|scratch|allocation/i.test(msg)) {
      return "Not enough memory. Lower Output quality in Settings or close other documents.";
    }
    if (!msg) return "Something went wrong. Nothing was changed.";
    return "Photoshop reported: " + msg.slice(0, 160);
  }

  function userError(message) {
    return new Error("GA: " + message);
  }

  function now() {
    return typeof performance !== "undefined" && performance.now ? performance.now() : Date.now();
  }

  return {
    SETTINGS_VERSION,
    SCHEMA,
    RANGES,
    LOOK_GROUPS,
    DEFAULT_SETTINGS,
    deepClone,
    clamp,
    roundToStep,
    toNumber,
    getPath,
    setPath,
    sanitizeValue,
    sanitizeNumber,
    sanitizeSettings,
    lookPart,
    applyLook,
    REF_SIDE,
    scaleLookToDoc,
    settingsEqual,
    isHex,
    normalizeHex,
    hexToRgb,
    rgbToHex,
    rgba,
    hexToHue,
    debounce,
    uid,
    versionAtLeast,
    formatValue,
    friendlyError,
    userError,
    now
  };
});

/*
 * Glow Aura — storage.js
 * Thin, defensive wrapper over plugin-local storage (UXP localStorage).
 * Stores: user presets, per-effect settings fallback, panel preferences.
 * Nothing ever leaves the machine.
 */
(function (root, factory) {
  if (root.GlowAura && root.GlowAura.__skipInstalled) return; // a live update is running instead
  "use strict";
  const api = factory();
  root.GlowAura = root.GlowAura || {};
  root.GlowAura.storage = api;
  if (typeof module === "object" && module && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const KEYS = {
    presets: "glowaura.userPresets.v1",
    effects: "glowaura.effects.v1",
    prefs: "glowaura.prefs.v1"
  };
  const MAX_EFFECTS = 500;

  function memoryBackend() {
    const m = {};
    return {
      getItem: (k) => (Object.prototype.hasOwnProperty.call(m, k) ? m[k] : null),
      setItem: (k, v) => {
        m[k] = String(v);
      },
      removeItem: (k) => {
        delete m[k];
      }
    };
  }

  /**
   * @param {{getItem:Function,setItem:Function,removeItem:Function}} [backend]
   */
  function createStorage(backend) {
    let be = backend;
    if (!be) {
      try {
        be = typeof localStorage !== "undefined" ? localStorage : memoryBackend();
      } catch (e) {
        be = memoryBackend();
      }
    }

    function read(key, fallback) {
      try {
        const raw = be.getItem(key);
        if (raw == null) return fallback;
        const v = JSON.parse(raw);
        return v == null ? fallback : v;
      } catch (e) {
        return fallback;
      }
    }

    function write(key, value) {
      try {
        be.setItem(key, JSON.stringify(value));
        return true;
      } catch (e) {
        return false;
      }
    }

    return {
      getUserPresets() {
        const v = read(KEYS.presets, []);
        return Array.isArray(v) ? v : [];
