   * image/selection: premultiplied colour; key = perceptual luminance
   * layer: premultiplied colour of the layer; key = alpha
   * outlines: band around the alpha edge in the layer's colour; key = band
   */
  function buildInput(src, s, scale) {
    const w = src.w;
    const h = src.h;
    const n = w * h;
    const r = plane(w, h);
    const g = plane(w, h);
    const b = plane(w, h);
    const key = plane(w, h);
    const mode = s.source.mode;

    if (mode === "outlines") {
      const sig = Math.max(0.6, (s.source.outline * scale) / 2);
      const ab = new F32(src.a);
      const rb = plane(w, h);
      const gb = plane(w, h);
      const bb = plane(w, h);
      for (let i = 0; i < n; i++) {
        rb[i] = src.r[i] * src.a[i];
        gb[i] = src.g[i] * src.a[i];
        bb[i] = src.b[i] * src.a[i];
      }
      const tmp = plane(w, h);
      gaussInPlace(ab, tmp, w, h, sig, sig);
      const csig = sig * 2;
      gaussInPlace(rb, tmp, w, h, csig, csig);
      gaussInPlace(gb, tmp, w, h, csig, csig);
      gaussInPlace(bb, tmp, w, h, csig, csig);
      // also blur alpha with the colour sigma to normalise colour
      const ac = new F32(src.a);
      gaussInPlace(ac, tmp, w, h, csig, csig);
      for (let i = 0; i < n; i++) {
        const band = Math.max(0, 1 - Math.abs(2 * ab[i] - 1));
        const e = band * band * (3 - 2 * band);
        let cr = 1;
        let cg = 1;
        let cb = 1;
        if (ac[i] > 1e-4) {
          cr = rb[i] / ac[i];
          cg = gb[i] / ac[i];
          cb = bb[i] / ac[i];
          const mx = Math.max(cr, cg, cb);
          if (mx > 1e-5) {
            cr /= mx;
            cg /= mx;
            cb /= mx;
          } else {
            cr = cg = cb = 1;
          }
        }
        r[i] = cr * e;
        g[i] = cg * e;
        b[i] = cb * e;
        key[i] = e;
      }
      return { r: r, g: g, b: b, key: key, keyed: true };
    }

    // A layer that covers most of the canvas (a photo) glows from its bright
    // parts like the whole image does; a sparse layer (text, logo, shape)
    // glows from its shape in its own colours.
    let cov = 0;
    if (mode === "layer") {
      for (let i = 0; i < n; i++) cov += src.a[i];
      cov /= Math.max(1, n);
    }
    const shapeKeyed = mode === "layer" && cov < 0.6;
    for (let i = 0; i < n; i++) {
      const al = src.a[i];
      const lr = src.r[i] * al;
      const lg = src.g[i] * al;
      const lb = src.b[i] * al;
      r[i] = lr;
      g[i] = lg;
      b[i] = lb;
      if (shapeKeyed) key[i] = al;
      else {
        const L = 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
        key[i] = encode1(L); // perceptual key, so threshold feels linear
      }
    }
    // brush & selection: the Glow Aura extraction, limited to the painted /
    // selected area (the mask is already in the alpha).
    return { r: r, g: g, b: b, key: key, keyed: shapeKeyed };
  }

  /** Highlight extraction. Returns planar r,g,b (linear) plus its peak. */
  /** Large-scale mean of the max channel (linear), for local-contrast gating. */
  function localMean(inp, w, h, frac) {
    const n = w * h;
    const m = plane(w, h);
    for (let i = 0; i < n; i++) m[i] = Math.max(inp.r[i], inp.g[i], inp.b[i]);
    let lv = { p: m, w: w, h: h };
    const sig = Math.max(0.8, frac * Math.max(w, h));
    let f = 1;
    while (sig / f > 8 && lv.w > 16 && lv.h > 16) {
      lv = down2(lv.p, lv.w, lv.h);
      f *= 2;
    }
    const work = new F32(lv.p);
    gaussInPlace(work, plane(lv.w, lv.h), lv.w, lv.h, sig / f, sig / f);
    const out = plane(w, h);
    addUp(out, w, h, work, lv.w, lv.h, 1);
    return out;
  }

  function extract(inp, n, threshold, transition, highlights, compression) {
    const r = new F32(n);
    const g = new F32(n);
    const b = new F32(n);
    const c = (compression / 100) * 3;
    const flatten = highlights === "flatten";
    const keyed = !!inp.keyed;
    const gate = !keyed && inp.local ? TUNE.localGate : 0;
    // Keyed modes (layer / outline / brush): the key is coverage, so a plain
    // soft step decides what glows. Image modes: a bright-pass that keeps only
    // the light ABOVE the threshold, with a quadratic soft knee. That keeps
    // midtones from turning into haze and lets real highlights bloom hard.
    const t = threshold;
    if (!keyed && t >= 0.995) return { r: r, g: g, b: b };
    const kLo = transition === "precise" ? t - 0.01 : t * 0.5;
    const kHi = transition === "precise" ? t + 0.01 : Math.min(1, t + 0.15);
    const T = TUNE.linearThreshold ? Math.min(0.999, t) : toLinear(Math.min(0.999, t));
    // The knee never reaches past white, so Threshold 1 really means "nothing".
    const knee = Math.max(1e-5, Math.min(T * (transition === "precise" ? 0.08 : 0.7), (1 - T) * 0.5));
    for (let i = 0; i < n; i++) {
      let lr = inp.r[i];
      let lg = inp.g[i];
      let lb = inp.b[i];
      let wgt;
      if (keyed) {
        wgt = smoothstep(kLo, kHi, inp.key[i]);
      } else {
        const br = Math.max(lr, lg, lb);
        if (br <= 1e-6) continue;
        if (TUNE.curve > 0) {
          const Lw = 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
          let e = (Lw - T) / (1 - T);
          if (transition !== "precise" && e < 0.1 && e > -0.1) e = ((e + 0.1) * (e + 0.1)) / 0.4;
          if (e <= 0) continue;
          wgt = Math.pow(Math.min(1, e), TUNE.curve);
        } else {
          let soft = br - T + knee;
          soft = soft < 0 ? 0 : soft > 2 * knee ? 2 * knee : soft;
          soft = (soft * soft) / (4 * knee);
          wgt = Math.max(soft, br - T) / br;
        }
        if (gate > 0 && wgt > 0) {
          // Only things brighter than their surroundings glow fully: text,
          // lights, the sun, edges. Big flat bright areas don't fog up.
          const ratio = (inp.near ? inp.near[i] : br) / (inp.local[i] + 0.02);
          wgt *= 1 - gate + gate * smoothstep(TUNE.localLo, TUNE.localHi, ratio);
        }
      }
      if (wgt <= 0) continue;
      const L = 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
      if (flatten) {
        const m = Math.max(lr, lg, lb);
        lr = lg = lb = m * 0.6 + L * 0.4;
      }
      // Dynamic-range compression: lift dimmer glow sources, keep peaks.
      const f = c > 0 ? (1 + c) / (1 + c * Math.min(1, L)) : 1;
      r[i] = lr * wgt * f;
      g[i] = lg * wgt * f;
      b[i] = lb * wgt * f;
    }
    return { r: r, g: g, b: b };
  }

  /**
   * Sum of `iterations` gaussians with radii doubling up to `radius`.
   * gamma shapes the falloff: <1 tight and punchy, >1 wide and airy.
   * Anisotropy (aspect) and rotation are applied in a rotated frame.
   */
  function bloomChannel(p, w, h, o) {
    const n = o.iterations;
    const sigmaMax = Math.max(0.5, o.radius / 2);
    const weights = [];
    let wsum = 0;
    // Gaussians smaller than ~0.2% of the document are invisible as a halo;
    // they're skipped (in DOCUMENT space, so preview and final look the same).
    const minSigma = (o.minSigmaDoc || 0) * (o.scaleToProxy || 1);
    let k0 = -1;
    for (let i = 0; i < n; i++) {
      const sig = sigmaMax / Math.pow(2, n - 1 - i);
      if (sig < minSigma && i < n - 1) {
        weights.push(0);
        continue;
      }
      if (k0 < 0) k0 = i;
      // tightest kept gaussian first; energy falls off with radius like a real
      // lens: gamma > 1 keeps more of the wide halo, < 1 stays tight.
      const wi = Math.pow(2, -(i - k0) * (TUNE.decay / o.gamma));
      weights.push(wi);
      wsum += wi;
    }
    const sqa = Math.sqrt(o.aspect);
    const rotated = o.aspect !== 1 && o.rotation !== 0;
    let fw = w;
    let fh = h;
    let base = p;
    if (rotated) {
      const fr = rotFrame(w, h, o.rotation);
      fw = fr.w;
      fh = fr.h;
      base = rotate(p, w, h, fw, fh, -o.rotation, true);
    }
    // Pyramid of the base; each gaussian is computed on the coarsest level that
    // still resolves it, accumulated per level, then cascaded up once.
    const pyr = [{ p: base, w: fw, h: fh }];
    const levelAcc = [];
    for (let i = 0; i < n; i++) {
      const sigma = sigmaMax / Math.pow(2, n - 1 - i);
      const sx = sigma * sqa;
      const sy = sigma / sqa;
      if (!weights[i]) continue;
      const smin = Math.min(sx, sy);
      let k = smin > 1.8 ? Math.floor(Math.log2(smin / 0.9)) : 0;
      k = Math.min(k, 9);
      while (pyr.length <= k) {
        const top = pyr[pyr.length - 1];
        if (top.w <= 4 || top.h <= 4) break;
        pyr.push(down2(top.p, top.w, top.h));
      }
      k = Math.min(k, pyr.length - 1);
      const lv = pyr[k];
      const f = Math.pow(2, k);
      const work = new F32(lv.p);
      gaussInPlace(work, plane(lv.w, lv.h), lv.w, lv.h, sx / f, sy / f);
      if (!levelAcc[k]) levelAcc[k] = plane(lv.w, lv.h);
      const la = levelAcc[k];
      const wk = weights[i] / wsum;
      for (let j = 0; j < la.length; j++) la[j] += wk * work[j];
    }
    for (let k = levelAcc.length - 1; k >= 1; k--) {
      if (!levelAcc[k]) continue;
      if (!levelAcc[k - 1]) levelAcc[k - 1] = plane(pyr[k - 1].w, pyr[k - 1].h);
      addUp(levelAcc[k - 1], pyr[k - 1].w, pyr[k - 1].h, levelAcc[k], pyr[k].w, pyr[k].h, 1);
      levelAcc[k] = null;
    }
    const acc = levelAcc[0] || plane(fw, fh);
    if (rotated) return rotate(acc, fw, fh, w, h, o.rotation, false);
    return acc;
  }

  /** Directional multi-pass streak filter (bidirectional). Works on a plane. */
  function streakChannel(p, w, h, dirs, lengthPx) {
    const out = plane(w, h);
    const passes = Math.max(1, Math.min(6, Math.ceil(Math.log(Math.max(4, lengthPx / 3)) / Math.log(4))));
    const atten = Math.pow(0.03, 1 / Math.max(4, lengthPx));
    for (let d = 0; d < dirs.length; d++) {
      const dx = Math.cos(dirs[d]);
      const dy = Math.sin(dirs[d]);
      for (let sign = -1; sign <= 1; sign += 2) {
        let cur = p;
        for (let pass = 0; pass < passes; pass++) {
          const step = Math.pow(4, pass);
          const nxt = plane(w, h);
          let norm = 0;
          const ws = [];
          for (let s = 0; s < 4; s++) {
            const wv = Math.pow(atten, step * s);
            ws.push(wv);
            norm += wv;
          }
          for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
              let acc = 0;
              for (let s = 0; s < 4; s++) {
                const off = step * s * sign;
                acc += ws[s] * sampleZero(cur, w, h, x + dx * off, y + dy * off);
              }
              nxt[y * w + x] = acc / norm;
            }
          }
          cur = nxt;
        }
        for (let i = 0; i < out.length; i++) out[i] += cur[i];
      }
    }
    return out;
  }

  /** Radial light scattering toward a centre (god rays). */
  function raysChannel(p, w, h, cx, cy, samples, spacing, falloff) {
    const out = plane(w, h);
    let norm = 0;
    for (let i = 0; i < samples; i++) norm += Math.pow(falloff, i);
    const inv = 1 / norm;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const vx = ((cx - x) * spacing) / samples;
        const vy = ((cy - y) * spacing) / samples;
        let fx = x;
        let fy = y;
        let wt = 1;
        let acc = 0;
        for (let i = 0; i < samples; i++) {
          acc += wt * sample(p, w, h, fx, fy);
          wt *= falloff;
          fx += vx;
          fy += vy;
        }
        out[y * w + x] = acc * inv;
      }
    }
    return out;
  }

  /** Hue rotation matrix around the grey axis (linear RGB). */
  function hueMatrix(deg) {
    const a = (deg * Math.PI) / 180;
    const c = Math.cos(a);
    const s = Math.sin(a);
    const k = 1 / 3;
    const sq = Math.sqrt(k);
    return [
      c + (1 - c) * k, k * (1 - c) - sq * s, k * (1 - c) + sq * s,
      k * (1 - c) + sq * s, c + k * (1 - c), k * (1 - c) - sq * s,
      k * (1 - c) - sq * s, k * (1 - c) + sq * s, c + k * (1 - c)
    ];
  }

  function hueToLinearRgb(hDeg) {
    const h = (((hDeg % 360) + 360) % 360) / 60;
    const x = 1 - Math.abs((h % 2) - 1);
    let r = 0;
    let g = 0;
    let b = 0;
    if (h < 1) [r, g, b] = [1, x, 0];
    else if (h < 2) [r, g, b] = [x, 1, 0];
    else if (h < 3) [r, g, b] = [0, 1, x];
    else if (h < 4) [r, g, b] = [0, x, 1];
    else if (h < 5) [r, g, b] = [x, 0, 1];
    else [r, g, b] = [1, 0, x];
    return [toLinear(r), toLinear(g), toLinear(b)];
  }

  function applyColor(R, G, B, n, color) {
    const sat = color.saturation / 100;
    if (color.colorize) {
      const c = hueToLinearRgb(color.hue < 0 ? color.hue + 360 : color.hue);
      const cl = 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
      const k0 = c[0] / cl;
      const k1 = c[1] / cl;
      const k2 = c[2] / cl;
      for (let i = 0; i < n; i++) {
        const Y = 0.2126 * R[i] + 0.7152 * G[i] + 0.0722 * B[i];
        R[i] = Y + (Y * k0 - Y) * sat;
        G[i] = Y + (Y * k1 - Y) * sat;
        B[i] = Y + (Y * k2 - Y) * sat;
      }
      return;
    }
    const doHue = color.hue !== 0;
    const doSat = sat !== 1;
    if (!doHue && !doSat) return;
    const m = hueMatrix(color.hue);
    const tint = TUNE.hueTint;
    for (let i = 0; i < n; i++) {
      let r = R[i];
      let g = G[i];
      let b = B[i];
      if (doHue) {
        // Rotate the glow's own colours, then push the shift a little further
        // so near-white glow still picks up a gentle tone (white stays light,
        // the image never turns one flat colour).
        const nr = m[0] * r + m[1] * g + m[2] * b;
        const ng = m[3] * r + m[4] * g + m[5] * b;
        const nb = m[6] * r + m[7] * g + m[8] * b;
        const Y0 = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        let tr = r + (nr - r) * tint;
        let tg = g + (ng - g) * tint;
        let tb = b + (nb - b) * tint;
        tr = tr > 0 ? tr : 0;
        tg = tg > 0 ? tg : 0;
        tb = tb > 0 ? tb : 0;
        const Y1 = 0.2126 * tr + 0.7152 * tg + 0.0722 * tb;
        const kY = Y1 > 1e-9 ? Y0 / Y1 : 1;
        r = tr * kY;
        g = tg * kY;
        b = tb * kY;
      }
      if (doSat) {
        const Y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        r = Math.max(0, Y + (r - Y) * sat);
        g = Math.max(0, Y + (g - Y) * sat);
        b = Math.max(0, Y + (b - Y) * sat);
      }
      R[i] = r;
      G[i] = g;
      B[i] = b;
    }
  }

  function aberrate(chs, w, h, ab, scale) {
    const pairIdx = { rb: [0, 2], rg: [0, 1], gb: [1, 2] }[ab.channels];
    const mix = ab.intensity / 100;
    const dist = ab.distance * scale;
    if (mix <= 0 || dist <= 0) return;
    const blurS = (ab.blur * scale) / 2;
    const ang = (ab.rotation * Math.PI) / 180;
    const ux = Math.cos(ang);
    const uy = Math.sin(ang);
    const cx = (w - 1) / 2;
    const cy = (h - 1) / 2;
    const half = Math.sqrt(cx * cx + cy * cy) || 1;
    for (let k = 0; k < 2; k++) {
      const ci = pairIdx[k];
      const sgn = k === 0 ? 1 : -1;
      const src = chs[ci];
      const shifted = plane(w, h);
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          let sx;
          let sy;
          if (ab.type === "radial") {
            const f = 1 - (sgn * dist) / half;
            sx = cx + (x - cx) * f;
            sy = cy + (y - cy) * f;
          } else {
            sx = x - ux * dist * sgn;
            sy = y - uy * dist * sgn;
          }
          shifted[y * w + x] = sampleZero(src, w, h, sx, sy);
        }
      }
      if (blurS > 0.35) gaussInPlace(shifted, plane(w, h), w, h, blurS, blurS);
      for (let i = 0; i < src.length; i++) src[i] = src[i] + (shifted[i] - src[i]) * mix;
    }
  }

  /** Finds the brightness-weighted centre of the highlights (0..100 %). */
  function autoCenter(prepared, s) {
    const inp = buildInput(prepared, s, 1);
    const n = prepared.w * prepared.h;
    const h = extract(inp, n, s.input.threshold, s.input.transition, s.input.highlights, 0);
    let sx = 0;
    let sy = 0;
    let sw = 0;
    for (let i = 0; i < n; i++) {
      const v = h.r[i] + h.g[i] + h.b[i];
      if (v <= 0) continue;
      const x = i % prepared.w;
      const y = (i / prepared.w) | 0;
      const v2 = v * v;
      sx += x * v2;
      sy += y * v2;
      sw += v2;
    }
    if (sw <= 0) return { x: 50, y: 35 };
    return {
      x: Math.round(((sx / sw) / Math.max(1, prepared.w - 1)) * 100),
      y: Math.round(((sy / sw) / Math.max(1, prepared.h - 1)) * 100)
    };
  }

  /* ------------------------------------------------------------------ */
  /* Main entry                                                          */
  /* ------------------------------------------------------------------ */

  /** Multiplies the glow by a painted mask (Uint8 0..255, any size). */
  function applyMask(out, w, h, mask) {
    const mw = mask.w;
    const mh = mask.h;
    const md = mask.data;
    const sx = mw / w;
    const sy = mh / h;
    const row = new F32(w);
    for (let y = 0; y < h; y++) {
      const my = Math.min(mh - 1, Math.max(0, Math.round((y + 0.5) * sy - 0.5)));
      for (let x = 0; x < w; x++) {
        const mx = Math.min(mw - 1, Math.max(0, Math.round((x + 0.5) * sx - 0.5)));
        row[x] = md[my * mw + mx] / 255;
      }
      const o = y * w;
      for (let x = 0; x < w; x++) {
        const k = row[x];
        out[0][o + x] *= k;
        out[1][o + x] *= k;
        out[2][o + x] *= k;
      }
    }
  }

  /**
   * The render, written as a generator that yields between heavy stages so the
   * panel can stay responsive (renderAsync) and stale renders can be dropped.
   * @param {{w,h,r,g,b,a}} src   from prepareSource()
   * @param {object} settings      any shape (sanitised)
   * @param {{scale:number, xray?:boolean, mask?:{w,h,data}}} opts
   */
  function* renderSteps(src, settings, opts) {
    const t0 = U.now();
    const s = U.sanitizeSettings(settings);
    const scale = Math.max(1e-4, (opts && opts.scale) || 1);
    const mask = opts && opts.mask && opts.mask.data ? opts.mask : null;
    const w = src.w;
    const h = src.h;
    const n = w * h;
    const inp = buildInput(src, s, scale);
    if (!inp.keyed && TUNE.localGate > 0) {
      inp.local = localMean(inp, w, h, TUNE.localSigma);
      // A tiny blur of the brightness so single sparkling pixels (leaves,
      // noise) don't count as light sources; real shapes still do.
      inp.near = localMean(inp, w, h, TUNE.nearSigma);
    }
    const hl = extract(inp, n, s.input.threshold, s.input.transition, s.input.highlights, s.input.compression);
    const out = [plane(w, h), plane(w, h), plane(w, h)];
    const hch = [hl.r, hl.g, hl.b];
    yield "input";

    if (opts && opts.xray) {
      for (let c = 0; c < 3; c++) for (let i = 0; i < n; i++) out[c][i] = encode1(Math.min(1, hch[c][i]));
      return { w: w, h: h, r: out[0], g: out[1], b: out[2], peak: 1, ms: Math.round(U.now() - t0) };
    }

    const mainK = s.main.opacity / 100;
    const coreK = s.main.core / 100;
    const bloomOpts = {
      minSigmaDoc: TUNE.minSigma * (Math.max(w, h) / scale),
      scaleToProxy: scale,
      iterations: s.main.iterations,
      radius: s.main.radius * scale,
      gamma: s.main.gamma,
      aspect: s.shape.aspect,
      rotation: (s.shape.rotation * Math.PI) / 180
    };
    const coreSigma = Math.max(0.6, s.main.radius * scale * TUNE.core);

    for (let c = 0; c < 3; c++) {
      const o = out[c];
      if (mainK > 0) {
        const bl = bloomChannel(hch[c], w, h, bloomOpts);
        for (let i = 0; i < n; i++) o[i] += mainK * bl[i];
      }
      if (coreK > 0) {
        const core = new F32(hch[c]);
        gaussInPlace(core, plane(w, h), w, h, coreSigma, coreSigma);
        for (let i = 0; i < n; i++) o[i] += coreK * core[i];
