  const DEVICE_KEY = "glowaura.device.v1";
  const DAY = 24 * 60 * 60 * 1000;
  const GRACE = 30 * DAY; // works offline this long after the last good check
  const CHECK_EVERY = DAY / 4; // re-check every 6 hours while online

  // Public half of the signing key; only the server can make valid notes.
  const N_HEX = "";
  const E = 65537;
  const DIGEST_INFO = "3031300d060960864801650304020105000420"; // SHA-256, PKCS#1 v1.5

