    const s = String(b64 || "").replace(/[^A-Za-z0-9+/]/g, "");
    let bits = 0;
    let acc = 0;
    let hex = "";
    for (let i = 0; i < s.length; i++) {
      acc = (acc << 6) | A.indexOf(s.charAt(i));
      bits += 6;
      if (bits >= 8) {
