    // a clock set before the last check also asks for a fresh check
    return { state: "ok", key: key, name: p.n, needsCheck: age > CHECK_EVERY || age < -DAY };
  }

  /* ---------- talking to the server ---------- */

  function withTimeout(promise, ms) {
    return Promise.race([
      promise,
      new Promise(function (_, rej) {
        setTimeout(function () {
          rej(new Error("timeout"));
        }, ms);
      })
    ]);
  }

  async function call(action, key, extra, fetchImpl) {
    const f = fetchImpl || (typeof fetch === "function" ? fetch : null);
    if (!f) return { ok: false, code: "offline" };
    const q = ["action=" + action, "key=" + encodeURIComponent(key), "device=" + encodeURIComponent(deviceId())];
    if (extra && extra.info) q.push("info=" + encodeURIComponent(extra.info));
    if (extra && extra.target) q.push("target=" + encodeURIComponent(extra.target));
    if (extra && extra.profile) ["name", "email", "phone"].forEach((k) => q.push(k + "=" + encodeURIComponent(extra.profile[k])));
    try {
      const res = await withTimeout(f(SERVER + "?" + q.join("&") + "&t=" + Date.now()), 25000);
      if (!res || !res.ok) return { ok: false, code: "offline" };
      const j = await res.json();
      return j && typeof j === "object" ? j : { ok: false, code: "server" };
    } catch (e) {
      return { ok: false, code: "offline" };
