  function accept(key, r) {
    const rec = { key: key, payload: r.payload, sig: r.sig };
    const p = readNote(rec, deviceId());
    if (!p) return { ok: false, code: "server" };
    save(rec);
    return { ok: true, name: p.n };
  }

  /**
   * Activates (or re-verifies) this PC.
   * @returns {Promise<{ok:true,name:string}|{ok:false,code:string,max?:number}>}
   *   codes: empty, invalid, revoked, limit, offline, server
   */
  async function activate(rawKey, opts) {
    const o = opts || {};
    const prof = cleanProfile(o.profile || profile());
    const bad = checkProfile(prof);
    if (bad) return { ok: false, code: bad };
    const key = normalizeKey(rawKey);
    if (!key) return { ok: false, code: rawKey && String(rawKey).trim() ? "invalid" : "empty" };
    if (!isKnownKey(key)) return { ok: false, code: "invalid" };
    const old = load() || {};
    save(Object.assign({}, old, { key: key, profile: prof }));
    const r = await call("activate", key, { info: deviceInfo(o.host), profile: prof }, o.fetch);
    if (!r.ok) {
      if (r.code === "invalid" || r.code === "revoked") drop(key);
      const pcs = Array.isArray(r.pcs)
        ? r.pcs.slice(0, 4).map((p) => ({ id: String(p.id || "").slice(0, 24), info: String(p.info || "PC").slice(0, 100), last: String(p.last || "").slice(0, 20) }))
        : [];
      return { ok: false, code: r.code || "server", max: r.max, pcs: pcs };
    }
    return accept(key, r);
  }

  /**
   * Online re-check of a saved license.
   * @returns {Promise<{ok:true}|{locked:true,code:string}|{offline:true}>}
   */
  async function refresh(opts) {
    const o = opts || {};
    const rec = load();
    if (!rec || !rec.key) return { locked: true, code: "none" };
    const r = await call("check", rec.key, null, o.fetch);
    if (r.ok) {
      const a = accept(rec.key, r);
      return a.ok ? { ok: true } : { offline: true };
    }
    if (r.code === "revoked" || r.code === "invalid" || r.code === "not_activated") {
      drop(rec.key);
      return { locked: true, code: r.code };
    }
    return { offline: true };
  }

  /**
   * Logs another PC out of this key (when both slots are taken), so this PC can log in.
   * @param {string} target the PC id from the "limit" answer
   */
  async function logoutOther(rawKey, target, opts) {
    const key = normalizeKey(rawKey);
    if (!key || !target) return { ok: false, code: "invalid" };
    const r = await call("logout", key, { target: target }, (opts || {}).fetch);
    return r.ok ? { ok: true } : { ok: false, code: r.code || "server" };
  }

  /** Frees this PC's slot so the key can be used on another computer. */
  async function deactivate(opts) {
    const o = opts || {};
    const rec = load();
    if (!rec || !rec.key) return { ok: true };
    const r = await call("deactivate", rec.key, null, o.fetch);
    if (!r.ok) return { ok: false, code: r.code || "server" };
    drop(rec.key);
    return { ok: true };
  }

  function maskKey(k) {
    const s = normalizeKey(k);
    return s ? s.slice(0, 7) + "-••••-" + s.slice(13) : "";
  }

  /** English messages for the activation screen (translated by the UI layer). */
  const MESSAGES = {
    empty: "Enter your license key.",
    need_name: "Enter your name.",
    need_email: "Enter a valid email address.",
    need_phone: "Enter your WhatsApp number.",
    invalid: "This key isn't valid. Check it and try again.",
    revoked: "This key has been turned off. Message Tawhid on WhatsApp for help.",
    limit: "This license key is already logged in on 2 PCs. Log out one of them to use Glow Aura on this PC.",
    not_activated: "This PC was logged out of your license key. Press Activate to log in again.",
    offline: "Couldn't reach the license server. Check your internet connection and try again.",
    server: "The license server had a problem. Try again in a minute.",
    expired: "Connect to the internet and press Activate to verify your license (needed once a month)."
  };

  return {
    SERVER: SERVER,
    BUY_URL: BUY_URL,
    GRACE: GRACE,
    CHECK_EVERY: CHECK_EVERY,
    MESSAGES: MESSAGES,
    normalizeKey: normalizeKey,
    maskKey: maskKey,
    deviceId: deviceId,
    deviceInfo: deviceInfo,
    status: status,
    activate: activate,
    refresh: refresh,
    deactivate: deactivate,
    profile: profile,
    logoutOther: logoutOther,
    isKnownKey: isKnownKey,
    verify: verify,
    _load: load
  };
});

