    try {
      if (isPainting()) await engine.endMaskPaint(true, null);
      const r = await engine.save(state.settings, { maxSide: state.outputSize });
      savePrefsNow();
      const msg = (r.updated ? "Glow updated" : "Glow saved") + " in " + r.ms + " ms.";
      toaster.show(r.warnings.length ? msg + " " + r.warnings[0] : msg, r.warnings.length ? "warning" : "success", 4200);
      engine.setTarget(null);
      state.xray = false;
      state.solo = false;
      setBusy(false);
      go("home");
    } catch (e) {
      setBusy(false);
      setStatus("error", "Save failed");
      toaster.show(U.friendlyError(e), "error");
    }
  }

  async function doCancel() {
    previewLater.cancel();
    state.pendingPreview = false;
    await waitIdle();
    if (engine) {
      setBusy(true, "Cancelling…");
      try {
        if (isPainting()) await engine.endMaskPaint(false, null);
        await engine.cancelPreview();
      } catch (e) {
        toaster.show(U.friendlyError(e), "error");
      }
      engine.setTarget(null);
      setBusy(false);
    }
    state.xray = false;
    state.solo = false;
    go("home");
  }

  async function startNew(look, modeOverride) {
    if (!engine) return;
    const ctx = engine.getContext();
    state.ctx = ctx;
    if (!ctx.ok) {
      toaster.show(ctx.message, "warning");
      return;
    }
    let mode = modeOverride || state.sourceMode;
    // Image source follows the Layers panel: one layer selected -> only that
    // layer glows (and the glow sits right above it); nothing selected -> the
    // whole image glows.
    if (mode === "image" && !modeOverride) {
      const L = ctx.layer;
      if (L && !L.isGroup && !L.elementId && !L.isPreview) mode = "layer";
    }
    let layerId = null;
    let layerName = "";
    if (mode === "layer" || mode === "outlines") {
      const L = ctx.layer;
      if (!L) return toaster.show("Select a layer in Photoshop first.", "warning");
      if (L.isGroup) return toaster.show("Groups can't glow on their own. Select a layer inside the group.", "warning");
      if (L.elementId || L.isPreview) return toaster.show("That's a Glow Aura layer. Select the layer you want to glow.", "warning");
      layerId = L.id;
      layerName = L.name;
    }
    // Every new glow starts from the "Glow Aura" look (or the look clicked),
    // scaled to this document's size, then the user tunes it.
    const startLook = look || presets.find("glow-aura").settings;
    const base = U.sanitizeSettings(U.applyLook(U.DEFAULT_SETTINGS, startLook));
    base.source = { mode: mode, layerId: layerId, layerName: layerName, outline: state.settings.source.outline };
    base.mask = { enabled: false };
    state.settings = U.sanitizeSettings(base);
    try {
      await engine.cancelPreview();
    } catch (e) {
      /* nothing to cancel */
    }
    engine.setTarget(null);
    state.tab = "glow";
    go("editor");
    runPreview();
  }

  async function startEdit(id) {
    if (!engine || state.busy) return;
    try {
      await engine.cancelPreview();
    } catch (e) {
      /* ignore */
    }
    const data = await engine.readEffect(id);
    if (!data) return toaster.show("That glow no longer exists.", "warning");
    engine.setTarget(id, data.uid);
    try {
      await engine.loadMaskFrom(id);
    } catch (e) {
      toaster.show("This glow's mask couldn't be read; it will be kept as it is.", "warning");
    }
    if (data.settings && data.settings.source.mode === "brush") {
      let ok = false;
      try {
        ok = await engine.loadBrushSource(data.uid);
      } catch (e) {
        ok = false;
      }
      if (!ok) {
        data.settings.source.mode = "image";
        toaster.show("The brushed area wasn't found, so this glow now uses the whole image. Use Repaint area to brush it again.", "warning", 6000);
      }
    }
    if (data.settings) {
      state.settings = data.settings;
    } else {
      state.settings = U.sanitizeSettings(U.DEFAULT_SETTINGS);
      toaster.show("Saved settings weren't found for this glow. Adjust and Save to rebuild it.", "warning", 5000);
    }
    state.tab = "glow";
    go("editor");
    if (state.auto) runPreview();
  }

  /* ------------------------------------------------------------------ */
  /* Photoshop sync                                                      */
  /* ------------------------------------------------------------------ */

  async function syncWithPhotoshop() {
    if (!engine) return;
    if (state.busy || Date.now() < state.quietUntil) {
      state.pendingSync = true;
      return;
    }
    const prevDoc = state.ctx && state.ctx.doc ? state.ctx.doc.id : null;
    state.ctx = engine.getContext();
    const docId = state.ctx.doc ? state.ctx.doc.id : null;
    if (state.view === "area") return; // the user is painting
    if (state.view === "editor") {
      if (!state.ctx.ok || docId !== prevDoc) {
        engine.setTarget(null);
        toaster.show("Document changed, so the edit was closed.", "warning");
        go("home");
        return;
      }
      if (isPainting()) return; // brush strokes are the user's own edits
      const ch = engine.checkUserChanges();
      if (ch.targetDeleted || ch.previewDeleted) {
        // The user removed the glow (delete or undo). Respect it: never bring it back.
        previewLater.cancel();
        state.pendingPreview = false;
        if (engine.abortRender) engine.abortRender();
        try {
          await engine.cancelPreview();
        } catch (e) {
          /* already gone */
        }
        engine.setTarget(null);
        toaster.show("The glow layer was removed, so the edit was closed.", "");
        go("home");
        return;
      }
      if (ch.previewHidden) {
        renderDock();
        return;
      }
      if (engine.sourceIsStale && engine.sourceIsStale()) setStatus("ok", "Image changed · tap Refresh to update the glow");
      return;
    }
    if (state.ctx.ok) {
      try {
        const n = await engine.cleanupStrays();
        if (n) toaster.show("Removed a leftover preview layer.", "");
      } catch (e) {
        /* non-critical */
      }
    }
    if (state.view === "home") mount();
  }

  const syncLater = U.debounce(syncWithPhotoshop, 260);

  function onPsEvent() {
    if (state.busy) {
      state.pendingSync = true;
      return;
    }
    syncLater();
  }

  /* Fallback watcher: some Photoshop builds don't deliver every notification,
     so a cheap poll catches layer selection / document / history changes. */
  let pollTimer = null;
  let lastSig = "";
  function signature() {
    try {
      const d = ps.app.activeDocument;
      if (!d) return "none";
      const a = d.activeLayers && d.activeLayers[0];
      const h = d.activeHistoryState;
      return [d.id, a ? a.id : 0, a ? a.name : "", h ? h.id : 0, d.layers ? d.layers.length : 0].join("|");
    } catch (e) {
      return "err";
    }
  }
  function startPolling() {
    if (pollTimer || !ps) return;
    lastSig = signature();
    pollTimer = setInterval(function () {
      if (state.busy) return;
      const sg = signature();
      if (sg !== lastSig) {
        lastSig = sg;
        syncLater();
      }
    }, 700);
  }
  function stopPolling() {
    if (pollTimer) clearInterval(pollTimer);
    pollTimer = null;
  }

  async function startListening() {
    startPolling();
    if (listening || !ps) return;
    try {
      await ps.action.addNotificationListener(PS_EVENTS, onPsEvent);
      listening = true;
    } catch (e) {
      listening = false;
    }
  }

  async function stopListening() {
    stopPolling();
    if (!listening || !ps) return;
    try {
      await ps.action.removeNotificationListener(PS_EVENTS, onPsEvent);
    } catch (e) {
      /* ignore */
    }
    listening = false;
  }

  /* ------------------------------------------------------------------ */
  /* Navigation                                                          */
  /* ------------------------------------------------------------------ */

  function licensed() {
    return state.license && state.license.state === "ok";
  }

  function go(view) {
    if (state.lockPending && view !== "editor" && view !== "area") {
      state.lockPending = false;
      state.license = GA.license ? GA.license.status() : { state: "none", key: "" };
    }
    if (view === "settings" && state.view !== "settings") state.returnView = state.view;
    if (view !== "editor") {
      previewLater.cancel();
      state.pendingPreview = false;
    }
    state.view = view;
    savePrefsLater();
    mount(true);
  }

  function mount(animate) {
    clearView();
    const vv = $("view");
    if (animate) {
      vv.classList.add("is-entering");
      setTimeout(function () {
        vv.classList.remove("is-entering");
      }, 30);
    }
    renderTop();
    const v = $("view");
    if (!licensed()) {
      if (state.view === "editor" || state.view === "area") state.view = "home";
      renderLicense(v);
      renderDock();
      return;
    }
    if (state.view === "editor") renderEditor(v);
    else if (state.view === "settings") renderSettings(v);
    else if (state.view === "area") renderArea(v);
    else renderHome(v);
    renderDock();
  }

  function renderTop() {
    const t = $("topActions");
    t.innerHTML = "";
    const sub = $("brandSub");
    if (state.view === "settings") {
      sub.textContent = T("Settings");
      t.appendChild(track(UI.button({ icon: "close", iconOnly: true, title: "Close settings", onPress: () => go(state.returnView || "home") })).el);
      return;
    }
    if (!licensed()) {
      sub.textContent = T("Activation");
      return;
    }
    const ctx = state.ctx;
    sub.textContent = ctx && ctx.doc ? ctx.doc.title : T("Works offline");
    t.appendChild(track(UI.button({ icon: "settings", iconOnly: true, title: "Settings & themes", onPress: () => go("settings") })).el);
  }

