  /* ------------------------------------------------------------------ */
  /* Editor                                                              */
  /* ------------------------------------------------------------------ */

  function addSlider(parent, path, label, hint, extra) {
    const s = track(
      UI.slider(
        Object.assign(
          {
            path: path,
            label: label,
            hint: hint,
            value: U.getPath(state.settings, path),
            onInput: function (val) {
              U.setPath(state.settings, path, val);
            },
            onCommit: function (val) {
              autoEnable(path);
              changed(path, val, true);
            }
          },
          extra || {}
        )
      )
    );
    parent.appendChild(s.el);
    return s;
  }

  function addSegRow(parent, path, label, options, hint) {
    const s = track(
      UI.segRow({
        label: label,
        hint: hint,
        value: U.getPath(state.settings, path),
        options: options,
        onChange: function (val) {
          autoEnable(path);
          changed(path, val, true);
        }
      })
    );
    parent.appendChild(s.el);
    return s;
  }

  const featureCards = {};

  function featureCard(title, icon, path, hint) {
    const c = track(
      UI.card({
        title: title,
        icon: icon,
        hint: hint,
        toggle: {
          value: U.getPath(state.settings, path),
          onChange: function (val) {
            changed(path, val, true);
            c.setDisabled(!val);
          }
        }
      })
    );
    c.setDisabled(!U.getPath(state.settings, path));
    featureCards[path.split(".")[0]] = c;
    return c;
  }

  /** Moving a slider of a switched-off effect switches it on (no dead sliders). */
  function autoEnable(path) {
    const g = path.split(".")[0];
    const card = featureCards[g];
    if (!card) return;
    if (state.settings[g] && state.settings[g].enabled === false) {
      changed(g + ".enabled", true, false);
      if (card.toggle) card.toggle.set(true);
      card.setDisabled(false);
      toaster.show(card.el.querySelector(".card-title").textContent + " turned on.", "", 1800);
    }
  }

  function renderEditor(v) {
    Object.keys(featureCards).forEach((k) => delete featureCards[k]);
    const sess = engine ? engine.getSession() : { targetId: null };
    const editing = !!sess.targetId;
    const s = state.settings;
    const srcLabel = { image: "Image", layer: "Layer", outlines: "Outline", selection: "Selection", brush: "Brushed area" }[s.source.mode];
    const name = editing ? (engine.listEffects().find((e) => e.id === sess.targetId) || { name: "Glow" }).name : "New glow";
    const sub = UI.h("div", { class: "subhead" }, [
      track(UI.button({ icon: "back", iconOnly: true, title: "Cancel and go back", onPress: doCancel })).el,
      UI.h("div", { class: "sub-text" }, [
        UI.h("div", { class: "sub-title", text: editing ? "Editing " + name : name }),
        UI.h("div", { class: "sub-meta", text: srcLabel + (s.source.layerName && (s.source.mode === "layer" || s.source.mode === "outlines") ? " · " + s.source.layerName : "") })
      ])
    ]);
    v.appendChild(sub);

    const tabs = track(
      UI.segmented({
        value: state.tab,
