  function renderFxTab(v) {
    const ca = featureCard("Chromatic aberration", "fx", "aberration.enabled", "Splits colour channels of the glow for a lens look.");
    addSegRow(ca.body, "aberration.type", "Type", [{ value: "offset", label: "Offset" }, { value: "radial", label: "Radial" }]);
    addSegRow(ca.body, "aberration.channels", "Channels", [{ value: "rb", label: "R·B" }, { value: "rg", label: "R·G" }, { value: "gb", label: "G·B" }]);
