  async function startAreaBrush(returnTo) {
    if (!engine || state.busy) return;
    const ctx = engine.getContext();
    if (!ctx.ok) return toaster.show(ctx.message, "warning");
    previewLater.cancel();
    setBusy(true, "Getting the brush ready…");
    try {
      if (returnTo === "editor") await engine.cancelPreview();
      await engine.beginBrushSelect(state.area);
      state.areaReturn = returnTo || "home";
      setBusy(false);
      go("area");
      toaster.show("Brush is ready. Paint on the image, then press OK.", "success", 4000);
    } catch (e) {
      setBusy(false);
      toaster.show(U.friendlyError(e), "error");
    }
  }

  async function finishArea(apply) {
    if (!engine || state.busy) return;
    setBusy(true, apply ? "Making the glow…" : "Cancelling…");
    let ok = false;
    try {
      ok = await engine.finishBrushSelect(apply);
    } catch (e) {
      setBusy(false);
      toaster.show(U.friendlyError(e), "warning", 5000);
      // Nothing painted: stay on the brush so they can paint and try again.
      if (apply) {
        try {
          await engine.beginBrushSelect(state.area);
        } catch (e2) {
          go(state.areaReturn);
        }
      }
      return;
    }
    setBusy(false);
    if (!apply) {
      go(state.areaReturn === "editor" ? "editor" : "home");
      if (state.areaReturn === "editor") runPreview();
      return;
    }
    if (ok && state.areaReturn === "editor") {
      changed("source.mode", "brush", false);
      go("editor");
      runPreview();
    } else if (ok) {
      startNew(null, "brush");
    }
  }

