  /** Glow ring behind a credit item; lights up on hover / click. */
  function glowWrap(child) {
    // warm ring for orange/red accents, cool ring for blue/purple ones
    const hue = U.hexToHue((resolvedTheme && resolvedTheme.vars && resolvedTheme.vars["--accent"]) || "#FF7A33");
    const cool = hue != null && hue > 170 && hue < 300;
    const ring = UI.h("img", { class: "glow-ring", src: cool ? "img/glow-ring-blue.png" : "img/glow-ring.png", alt: "" });
    ring.style.opacity = "0";
    const w = UI.h("span", { class: "glow-wrap" }, [ring, child]);
    w._ring = ring;
    return w;
  }

  /**
   * Credit card light: a soft CC-Light-Sweep style band crosses the card and
   * the hovered item gets a warm glow ring. Pure JS tweening (works in UXP).
   */
  function lightUp(card, sweep, wrap) {
    const now = Date.now();
    if (card._sweepUntil && now < card._sweepUntil && !wrap) return;
    const W = card.getBoundingClientRect ? card.getBoundingClientRect().width || 300 : 300;
    const D = 720;
    card._sweepUntil = now + D;
    if (card._sweepTimer) clearInterval(card._sweepTimer);
    const ring = wrap ? wrap._ring : null;
    const t0 = now;
    card._sweepTimer = setInterval(function () {
      const t = Math.min(1, (Date.now() - t0) / D);
      const e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      sweep.style.left = (-90 + (W + 120) * e).toFixed(1) + "px";
      sweep.style.opacity = String(Math.sin(Math.PI * t) * 0.95);
      if (ring) ring.style.opacity = String(Math.sin(Math.PI * Math.min(1, t * 1.15)) * 0.95);
      if (t >= 1) {
        clearInterval(card._sweepTimer);
        card._sweepTimer = null;
        sweep.style.opacity = "0";
        if (ring) ring.style.opacity = "0";
      }
    }, 16);
  }

  function creditCard() {
    const fb = UI.h("img", { class: "social", src: "img/facebook.png", alt: "Facebook", title: "Facebook · tawhid.ahmed.gfx" });
    const be = UI.h("img", { class: "social", src: "img/behance.png", alt: "Behance", title: "Behance · tawhidahmedgfx" });
    const wa = UI.h("img", { class: "social", src: "img/whatsapp.png", alt: "WhatsApp", title: "WhatsApp · 01343175562" });
    disposers.push(UI.press(fb, () => openLink(SOCIAL.facebook)));
    disposers.push(UI.press(be, () => openLink(SOCIAL.behance)));
    disposers.push(UI.press(wa, () => openLink(SOCIAL.whatsapp)));
    const av = glowWrap(UI.h("img", { class: "avatar", src: "img/avatar.png", alt: "Tawhid Ahmed" }));
    av.classList.add("is-avatar");
    const wraps = [av, glowWrap(fb), glowWrap(be), glowWrap(wa)];
    const sweep = UI.h("img", { class: "sweep", src: "img/sweep.png", alt: "" });
    sweep.style.opacity = "0";
    const card = UI.h("div", { class: "credit" }, [
      wraps[0],
      UI.h("div", { class: "credit-text" }, [UI.h("div", { class: "credit-by", text: "Made by" }), UI.h("div", { class: "credit-name", text: "Tawhid Ahmed" })]),
      UI.h("div", { class: "credit-social" }, wraps.slice(1)),
      sweep
    ]);
    wraps.forEach(function (w) {
      const go = () => lightUp(card, sweep, w);
      ["mouseenter", "pointerdown"].forEach(function (ev) {
        w.addEventListener(ev, go);
        disposers.push(() => w.removeEventListener(ev, go));
      });
    });
    const goCard = () => lightUp(card, sweep, null);
    card.addEventListener("mouseenter", goCard);
    disposers.push(() => card.removeEventListener("mouseenter", goCard));
    disposers.push(() => card._sweepTimer && clearInterval(card._sweepTimer));
    return card;
  }

