  /* ---------- looks (presets) ---------- */

  function loadLook(p) {
    const scaled = U.sanitizeSettings(U.applyLook(U.DEFAULT_SETTINGS, p.settings));
    state.settings = U.applyLook(state.settings, U.lookPart(scaled));
    savePrefsLater();
    toaster.show("Loaded " + p.name + ".", "");
    state.tab = "glow";
    mount();
    if (state.auto) previewLater();
  }

  function lookItem(p) {
    const it = UI.h("div", { class: "item" });
    it.appendChild(UI.iconEl(p.builtIn ? "sparkle" : "looks", "item-ic"));
    if (state.renamingId === p.id) {
      const input = UI.h("input", { class: "rename", type: "text", value: p.name, "aria-label": "Look name" });
      const commit = function () {
        try {
          presets.rename(p.id, input.value);
        } catch (e) {
          toaster.show(U.friendlyError(e), "error");
        }
        state.renamingId = null;
        mount();
      };
      input.addEventListener("keydown", function (e) {
        e.stopPropagation();
        if (e.key === "Enter") commit();
        else if (e.key === "Escape") {
          state.renamingId = null;
          mount();
        }
      });
      input.addEventListener("blur", commit);
      input.addEventListener("click", (e) => e.stopPropagation());
      it.appendChild(input);
      setTimeout(function () {
        try {
          input.focus();
        } catch (e) {
          /* optional */
        }
      }, 0);
      return it;
    }
    it.appendChild(UI.h("span", { class: "item-name", text: p.name }));
    if (!p.builtIn) {
      it.appendChild(
        track(
          UI.button({
            icon: "rename",
            iconOnly: true,
            variant: "ghost",
            title: "Rename",
            onPress: function (e) {
              e.stopPropagation();
              state.renamingId = p.id;
              mount();
            }
          })
        ).el
      );
      const confirming = state.confirmDeleteId === p.id;
      it.appendChild(
        track(
          UI.button({
            icon: confirming ? "check" : "trash",
            iconOnly: true,
            variant: "ghost",
            title: confirming ? "Click again to delete" : "Delete",
            onPress: function (e) {
              e.stopPropagation();
              if (state.confirmDeleteId !== p.id) {
                state.confirmDeleteId = p.id;
                mount();
                setTimeout(function () {
                  if (state.confirmDeleteId === p.id) {
                    state.confirmDeleteId = null;
                    if (state.view === "editor" && state.tab === "looks") mount();
                  }
                }, 3000);
                return;
              }
              state.confirmDeleteId = null;
              presets.remove(p.id);
              toaster.show("Deleted " + p.name + ".", "");
              mount();
            }
          })
        ).el
      );
    }
    disposers.push(UI.press(it, () => loadLook(p)));
    return it;
  }

  async function importLooks() {
    if (!uxp) return;
    try {
      const file = await uxp.storage.localFileSystem.getFileForOpening({ types: ["json"] });
      if (!file) return;
      const r = presets.importJSON(await file.read());
      toaster.show(r.added ? "Imported " + r.added + " look" + (r.added === 1 ? "" : "s") + (r.skipped ? " (" + r.skipped + " skipped)." : ".") : "No valid looks in that file.", r.added ? "success" : "warning");
      mount();
    } catch (e) {
      toaster.show(U.friendlyError(e), "error");
    }
  }

  async function exportLooks() {
    if (!uxp) return;
    const user = presets.user();
    try {
      const file = await uxp.storage.localFileSystem.getFileForSaving("glow-aura-looks.json", { types: ["json"] });
      if (!file) return;
      await file.write(presets.exportJSON(user.length ? "user" : "all"));
      toaster.show(user.length ? "Exported " + user.length + " look" + (user.length === 1 ? "" : "s") + "." : "No saved looks yet, so the built-ins were exported.", "success");
    } catch (e) {
      toaster.show(U.friendlyError(e), "error");
    }
  }

  function renderLooksTab(v) {
    const save = track(UI.card({ title: "Save this look", icon: "save" }));
    const form = UI.h("div", { class: "inline" });
    const input = UI.h("input", { type: "text", placeholder: "Look name", maxlength: "40", "aria-label": "Look name" });
    const doSaveLook = function () {
      try {
        // store looks at the reference size so they fit any document later
        const r = presets.save(input.value, state.settings);
        toaster.show((r.overwritten ? "Updated " : "Saved ") + r.preset.name + ".", "success");
        mount();
      } catch (e) {
        toaster.show(U.friendlyError(e), "warning");
      }
    };
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") doSaveLook();
    });
    form.appendChild(input);
    form.appendChild(track(UI.button({ label: "Save", icon: "save", size: "sm", variant: "primary", iconColor: resolvedTheme.vars["--primary-fg"], onPress: doSaveLook })).el);
    save.body.appendChild(form);
    v.appendChild(save.el);

    const mine = track(UI.card({ title: "Your looks", icon: "looks" }));
    const user = presets.user();
    if (!user.length) mine.body.appendChild(UI.emptyState("looks", "No saved looks yet", "Dial in a glow and save it above. Looks are stored on this computer."));
    else {
      const ul = UI.h("div", { class: "list" });
      user.forEach((p) => ul.appendChild(lookItem(p)));
      mine.body.appendChild(ul);
    }
    const row = UI.h("div", { class: "btn-row" });
    row.appendChild(track(UI.button({ label: "Import", icon: "import", size: "sm", onPress: importLooks })).el);
    row.appendChild(track(UI.button({ label: "Export", icon: "export", size: "sm", onPress: exportLooks })).el);
    mine.body.appendChild(row);
    v.appendChild(mine.el);

