  function renderDock() {
    const dock = $("dock");
    dock.innerHTML = "";
    document.body.classList.toggle("has-dock", state.view === "editor");
    if (state.view !== "editor") {
      dock.style.display = "none";
      return;
    }
    dock.style.display = "block";
    const sess = engine ? engine.getSession() : { hasPreview: false, targetId: null, showingEffect: true };

    const st = UI.h("div", { class: "status", id: "status" }, [UI.h("span", { class: "led" }), UI.h("span", { class: "status-text", text: state.status.text })]);
    const r1 = UI.h("div", { class: "dock-row" }, [st]);
    dock.appendChild(r1);
    setStatus(state.status.kind, state.status.text);

    const tools = UI.h("div", { class: "dock-row tools" });
    const auto = track(
      UI.tool({
        icon: "auto",
        label: "Auto",
        title: "Auto update: re-render after every change",
        on: state.auto,
        onPress: function () {
          state.auto = !state.auto;
          auto.set(state.auto);
          savePrefsLater();
          if (state.auto) previewLater();
        }
      })
    );
    const xray = track(
      UI.tool({
        icon: "xray",
        label: "xRay",
        title: "xRay: show the highlights the glow is made from",
        on: state.xray,
        onPress: function () {
          state.xray = !state.xray;
          xray.set(state.xray);
          runPreview();
        }
      })
    );
    const solo = track(
      UI.tool({
        icon: "solo",
        label: "Solo",
        title: "Solo: show only the glow on black",
        on: state.solo,
        onPress: function () {
          state.solo = !state.solo;
          solo.set(state.solo);
          runPreview();
        }
      })
    );
    const eye = track(
      UI.tool({
        icon: sess.showingEffect ? "eye" : "eyeOff",
        label: sess.showingEffect ? "After" : "Before",
        title: "Before / After",
        onPress: async function () {
          if (!engine || state.busy) return;
          const s2 = engine.getSession();
          if (!s2.hasPreview && !s2.targetId) return toaster.show("Nothing to compare yet. Render a preview first.", "");
          try {
            await engine.setShowEffect(!s2.showingEffect);
          } catch (e) {
            toaster.show(U.friendlyError(e), "error");
          }
          renderDock();
        }
      })
    );
    const refresh = track(
      UI.tool({
        icon: "refresh",
        label: "Refresh",
        title: "Re-read the image and render",
        onPress: function () {
          if (engine) engine.invalidateSource();
          runPreview();
        }
      })
    );
    [auto, xray, solo, eye, refresh].forEach((t) => tools.appendChild(t.el));
    dock.appendChild(tools);

    const actions = UI.h("div", { class: "dock-row actions" });
    actions.appendChild(track(UI.button({ label: "Cancel", variant: "glass", onPress: doCancel })).el);
    actions.appendChild(
      track(
        UI.button({
          label: sess.targetId ? "Update" : "Save",
          icon: "check",
          variant: "primary",
          iconColor: resolvedTheme.vars["--primary-fg"],
          title: "Render at output quality and add to the document (one undo step)",
          onPress: doSave
        })
      ).el
    );
    dock.appendChild(actions);
  }

