  function setAppearance(patch) {
    state.appearance = TH.sanitizePrefs(Object.assign({}, state.appearance, patch));
    savePrefsLater();
    applyTheme();
    mount();
  }

  async function pickInto(key) {
    if (!engine) return;
    try {
      const cur = key === "accent" ? state.appearance.accent || resolvedTheme.theme.accent : resolvedTheme.vars["--text"];
      const hex = await engine.pickColor(cur);
      if (hex) setAppearance({ [key]: hex });
    } catch (e) {
      toaster.show(U.friendlyError(e), "error");
    }
  }

  async function chooseWallpaper() {
    if (!uxp) return;
    try {
      const fs = uxp.storage.localFileSystem;
      const file = await fs.getFileForOpening({ types: ["jpg", "jpeg", "png"] });
      if (!file) return;
      const folder = await fs.getDataFolder();
      const ext = /\.png$/i.test(file.name) ? "png" : "jpg";
      const name = "wallpaper-" + Date.now() + "." + ext;
      const data = await file.read({ format: uxp.storage.formats.binary });
      const out = await folder.createFile(name, { overwrite: true });
      await out.write(data, { format: uxp.storage.formats.binary });
      const old = state.appearance.customWallpaper;
      setAppearance({ customWallpaper: name, wallpaper: true });
      if (old) {
        try {
          const prev = await folder.getEntry(old);
          await prev.delete();
        } catch (e) {
          /* already gone */
        }
      }
      toaster.show("Wallpaper set.", "success");
    } catch (e) {
      toaster.show(U.friendlyError(e), "error");
    }
  }

