  const LICENSE_HELP = "https://wa.me/8801343175562?text=" + encodeURIComponent("Assalamu Alaikum Tawhid bhai! I need help with my Glow Aura license key.");

  function licenseMessage(code) {
    const M = GA.license ? GA.license.MESSAGES : {};
    return M[code] || M.server || "Something went wrong. Nothing was changed.";
  }

  function renderLicense(v) {
    const L = state.license || {};
    if (!state.licMsg && L.state === "expired") state.licMsg = licenseMessage("expired");
    if (!state.licInput && L.key) state.licInput = L.key;
    if (!state.licForm) {
      const saved = GA.license ? GA.license.profile() : { name: "", email: "", phone: "" };
      state.licForm = saved;
      state.licSaved = !!(saved.name || saved.email || saved.phone);
    }

    v.appendChild(
      UI.h("div", { class: "hero" }, [
        UI.h("img", { src: resolvedTheme.darkUi ? "img/logo-hero.png" : "img/logo-hero-dark.png", alt: "" }),
        UI.h("div", { class: "hero-title", text: "Activate Glow Aura" }),
        UI.h("div", { class: "hero-sub", text: "Fill in your details and the license key you got after buying Glow Aura." })
      ])
    );

    const c = track(UI.card({ title: "Your details", icon: "check" }));
    if (state.licSaved) c.body.appendChild(UI.h("div", { class: "lic-saved", text: "Your saved details are filled in. Just press Activate." }));
    const inputs = [];
    function field(label, opts, get, set, note) {
      c.body.appendChild(UI.h("div", { class: "lic-label", text: label }));
      const el = UI.h("input", Object.assign({ class: "lic-input", type: "text", value: get(), spellcheck: "false", "aria-label": label }, opts));
      el.addEventListener("input", function () {
        set(el.value);
      });
      el.addEventListener("keydown", function (e) {
        if (e.key === "Enter") doActivate();
      });
      c.body.appendChild(el);
      if (note) c.body.appendChild(UI.h("div", { class: "lic-note", text: note }));
      inputs.push(el);
      return el;
    }
    const F = state.licForm;
    field("Your name", { placeholder: "Full name", maxlength: "60" }, () => F.name, (x) => (F.name = x));
    field("Email address", { type: "email", placeholder: "you@gmail.com", maxlength: "100" }, () => F.email, (x) => (F.email = x), "Use an email you check often. Updates are sent here.");
    field("WhatsApp number", { type: "tel", placeholder: "01XXXXXXXXX", maxlength: "20" }, () => F.phone, (x) => (F.phone = x));
    const input = field("License key", { class: "lic-input lic-key", placeholder: "GA-XXXX-XXXX-XXXX", maxlength: "24" }, () => state.licInput, (x) => (state.licInput = x));
    if (state.licMsg) c.body.appendChild(UI.h("div", { class: "lic-msg", text: state.licMsg }));
    (state.licPcs || []).forEach(function (pc, i) {
      const asking = state.confirmLogout === pc.id;
      const pcLabel = "PC " + (i + 1) + ": " + pc.info;
      c.body.appendChild(
        UI.h("div", { class: "lic-pc" }, [
          UI.h("div", { class: "lic-pc-info" }, [
            UI.h("b", { text: pcLabel }),
            UI.h("span", { text: pc.last ? "Last used " + pc.last : "" })
          ]),
          track(
            UI.button({
              label: state.licBusy && asking ? "Logging out…" : asking ? "Yes, log out" : "Log out",
              size: "sm",
              variant: asking ? "primary" : "glass",
              onPress: () => doLogoutOther(pc.id)
            })
          ).el
        ])
      );
    });
    c.body.appendChild(
      track(
        UI.button({
          label: state.licBusy ? "Activating…" : "Activate",
          icon: "check",
          variant: "primary",
          iconColor: resolvedTheme.vars["--primary-fg"],
          onPress: doActivate
        })
      ).el
    );
    c.body.appendChild(UI.h("div", { class: "hint", text: "One key works on 2 PCs. You need internet once to activate." }));
    v.appendChild(c.el);

    const h = track(UI.card({ title: "No key yet?", icon: "info" }));
    const row = UI.h("div", { class: "btn-row" });
    row.appendChild(track(UI.button({ label: "Buy Glow Aura", icon: "export", size: "sm", onPress: () => openLink(GA.license ? GA.license.BUY_URL : "") })).el);
    row.appendChild(track(UI.button({ label: "Help on WhatsApp", size: "sm", variant: "ghost", onPress: () => openLink(LICENSE_HELP) })).el);
    h.body.appendChild(row);
    v.appendChild(h.el);

    const lg = track(UI.card({ title: "Language", icon: "info" }));
    lg.body.appendChild(
      track(
        UI.segmented({
          value: state.lang,
          options: I18N.LANGS,
          onChange: function (val) {
            state.lang = val;
            applyLang();
            savePrefsNow();
            mount(false);
          }
        })
      ).el
    );
    v.appendChild(lg.el);
    v.appendChild(UI.h("div", { class: "about" }, [UI.h("span", { class: "about-ver", text: "Glow Aura " + VERSION })]));
    const empty = inputs.find((el) => !el.value);
    if (!state.licBusy && empty) setTimeout(() => empty.focus && empty.focus(), 50);
    void input;
  }

  async function doActivate(doneMsg) {
    if (state.licBusy || !GA.license) return;
    state.licBusy = true;
    state.licMsg = "";
    state.licPcs = [];
    state.confirmLogout = "";
    mount(false);
    const r = await GA.license.activate(state.licInput, { host: hostVersion(), profile: state.licForm });
    state.licBusy = false;
    if (r.ok) {
      state.license = GA.license.status();
      state.licMsg = "";
      state.view = "home";
      mount(true);
      toaster.show(typeof doneMsg === "string" ? doneMsg : "Glow Aura activated. Welcome, " + (r.name || "friend") + "!", "success", 5000);
      return;
    }
    state.license = GA.license.status();
    state.licMsg = licenseMessage(r.code);
    state.licPcs = r.code === "limit" ? r.pcs || [] : [];
    mount(false);
  }

  /** Both PCs are taken: log one out (asks twice), then log this PC in. */
  async function doLogoutOther(id) {
    if (state.licBusy || !GA.license) return;
    if (state.confirmLogout !== id) {
      state.confirmLogout = id;
      mount(false);
      return;
    }
    state.licBusy = true;
    mount(false);
    const r = await GA.license.logoutOther(state.licInput, id);
    state.licBusy = false;
    state.confirmLogout = "";
    if (!r.ok) {
      state.licMsg = licenseMessage(r.code);
      mount(false);
      return;
    }
    await doActivate("The other PC was logged out. Glow Aura is now active on this PC.");
  }

  async function doDeactivate() {
    if (state.licBusy || !GA.license) return;
    if (!state.confirmDeactivate) {
      state.confirmDeactivate = true;
      mount(false);
      setTimeout(function () {
        if (state.confirmDeactivate && !state.licBusy) {
          state.confirmDeactivate = false;
          if (state.view === "settings") mount(false);
        }
      }, 4000);
      return;
    }
    state.confirmDeactivate = false;
    state.licBusy = true;
    state.licMsg = "";
    mount(false);
    const r = await GA.license.deactivate();
    state.licBusy = false;
    if (!r.ok) {
      state.licMsg = licenseMessage(r.code);
      mount(false);
      return;
    }
    state.license = GA.license.status();
    state.licForm = null; // filled again from the saved details
    state.licMsg = "Logged out of this PC. Your key can now be used on another computer.";
    state.view = "home";
    mount(true);
  }

  /** Quiet online re-check every few days; locks the panel if the key was turned off. */
  async function refreshLicense(force) {
    if (!GA.license || !licensed() || (!force && !state.license.needsCheck)) return;
    const r = await GA.license.refresh();
    if (r.ok) {
      state.license = GA.license.status();
      return;
    }
    if (r.locked) {
      state.licMsg = licenseMessage(r.code);
      if (state.view === "editor" || state.view === "area") {
        state.lockPending = true; // finish the current glow first
        return;
      }
      state.license = GA.license.status();
      state.view = "home";
      mount(false);
    }
  }

  /* ------------------------------------------------------------------ */
  /* Boot                                                                */
  /* ------------------------------------------------------------------ */

  function block(title, text) {
    $("blockerTitle").textContent = T(title);
    $("blockerText").textContent = T(text);
    $("blocker").classList.add("is-visible");
    $("app").style.display = "none";
  }

  function hostVersion() {
    try {
      return (uxp && uxp.host && uxp.host.version) || (ps && ps.app && ps.app.version) || "";
    } catch (e) {
      return "";
    }
  }

  function applyLang() {
    I18N.setLang(state.lang);
    document.body.classList.toggle("lang-bn", state.lang === "bn");
  }

  function boot() {
    applyLang();
    applyTheme();
    onResize();
    window.addEventListener("resize", onResize);
    $("wallpaper").addEventListener("load", layoutWallpaper);

    if (!ps || !uxp) {
      block("Glow Aura", "This panel runs inside Adobe Photoshop 24.4 or later.");
      return;
    }
    const v = hostVersion();
    if (v && !U.versionAtLeast(v, MIN_PS)) {
      block("Update Photoshop", "Glow Aura needs Photoshop 24.4 or later. You're running " + v + ". Update from the Creative Cloud app, then reopen this panel.");
      return;
    }
    if (!ps.imaging) {
      block("Update Photoshop", "This Photoshop doesn't expose the Imaging API Glow Aura renders with. Update to the latest version.");
      return;
    }

    engine = GA.glow.createEngine({
      app: ps.app,
      action: ps.action,
      core: ps.core,
      imaging: ps.imaging,
      constants: ps.constants,
      storage: storage
    });
    state.ctx = engine.getContext();
    mount();
    startListening();
    syncWithPhotoshop();
    refreshLicense(true);
    // Look for a newer Glow Aura a few seconds after start-up, then every
    // 30 minutes while the panel stays open (quietly).
    updateTimers.push(
      setTimeout(function () {
        checkForUpdate(false);
      }, 3000)
    );
    updateTimers.push(
      setInterval(function () {
        checkForUpdate(false);
        if (GA.license && licensed()) {
          const st = GA.license.status();
          if (st.state === "ok") {
            state.license = st;
            refreshLicense();
          } else if (state.view === "editor" || state.view === "area") state.lockPending = true;
          else {
            state.license = st;
            mount(false);
          }
        }
      }, 30 * 60 * 1000)
    );
    if (GA.boot && GA.boot.justUpdated) {
      const v = GA.boot.justUpdated;
      GA.boot.justUpdated = null;
      setTimeout(() => toaster.show("Glow Aura updated to v" + v + ".", "success", 5000), 400);
    }
  }

  const updateTimers = [];

  /* ---------- updates ---------- */

  async function checkForUpdate(manual) {
    if (!GA.updater) return;
    if (manual) {
      state.updateStatus = "Checking for updates…";
      if (state.view === "settings") mount(false);
    }
    const r = await GA.updater.check(VERSION);
    const now = new Date();
    state.lastChecked = ("0" + now.getHours()).slice(-2) + ":" + ("0" + now.getMinutes()).slice(-2);
    if (r.available) {
      state.update = r;
      state.updateStatus = "";
      if (manual) state.skipVersion = "";
      showUpdateNotice();
    } else {
      state.update = null;
      state.updateStatus = !manual ? "" : r.offline ? "Couldn't reach the update server. Check your internet connection and try again." : "Glow Aura is up to date.";
    }
    if (state.view === "home" || state.view === "settings") mount(false);
  }

  /** Update pop-up: always English, visible on every screen until closed. */
  function showUpdateNotice() {
    const u = state.update;
    const box = $("updateNotice");
    if (!box || !u || state.noticeClosed === u.version) return;
    $("unTitle").textContent = "New update available · v" + u.version;
    $("unSub").textContent = "Click Update to install the latest Glow Aura.";
    box.classList.add("is-visible");
    if (!box._wired) {
      box._wired = true;
      UI.press($("unUpdate"), function () {
        box.classList.remove("is-visible");
        runUpdate();
      });
      UI.press($("unClose"), function () {
        state.noticeClosed = state.update ? state.update.version : "";
        box.classList.remove("is-visible");
      });
    }
  }

  /** After download: clear steps in the (English) update pop-up. */
  function showSteps(path) {
    const box = $("updateNotice");
    if (!box) return;
    $("unTitle").textContent = "Update downloaded";
    $("unSub").textContent = "1. Close Photoshop.  2. Double-click " + (path ? path.split(/[\\/]/).pop() : "the downloaded .ccx file") + ".  3. Open Photoshop again.";
    $("unUpdate").style.display = "none";
    box.classList.add("is-visible");
  }

  async function runUpdate() {
    if (!state.update || state.busy) return;
    const live = GA.updater.canLive(state.update);
    setBusy(true, live ? "Updating Glow Aura…" : "Downloading the update…");
    let r;
    try {
      r = await GA.updater.install(state.update);
    } catch (e) {
      setBusy(false);
      setStatus("ok", "Ready");
      toaster.show(U.friendlyError(e), "error");
      return;
    }
    // A live update already replaced this panel with the new version.
    if (r.how === "live" && r.ok) return;
    setBusy(false);
    setStatus("ok", "Ready");
    if (r.how === "saved") {
      state.updateStatus = "Update saved. Close Photoshop, then double-click " + (r.path.split(/[\\/]/).pop() || "the .ccx file") + " to install it.";
      showSteps(r.path);
    } else if (r.how === "browser") {
      state.updateStatus = "The update is downloading in your browser. Close Photoshop, then double-click the downloaded file to install it.";
      showSteps("");
    }
    if (state.view === "settings" || state.view === "home") mount(false);
  }

  function updateBanner() {
    const u = state.update;
    if (!u || state.skipVersion === u.version) return null;
    const notes = (state.lang === "bn" ? u.notes.bn : u.notes.en) || "";
    const later = track(
      UI.button({
        label: "Later",
        title: "Later",
        size: "sm",
        variant: "ghost",
        onPress: function () {
          state.skipVersion = u.version;
          savePrefsNow();
          mount(false);
        }
      })
    );
    const now = track(UI.button({ label: "Update now", icon: "export", size: "sm", variant: "primary", onPress: runUpdate }));
    return UI.h("div", { class: "update-card" }, [
      UI.h("div", { class: "update-title", text: "Update available · v" + u.version }),
      notes ? UI.h("div", { class: "update-notes", text: notes }) : null,
      UI.h("div", { class: "btn-row" }, [now.el, later.el])
    ]);
  }

  async function teardown() {
    updateTimers.forEach((t) => {
      clearTimeout(t);
      clearInterval(t);
    });
    updateTimers.length = 0;
    previewLater.cancel();
    syncLater.cancel();
    savePrefsLater.cancel();
    savePrefsNow();
    await stopListening();
    clearView();
    window.removeEventListener("resize", onResize);
  }

  const panelCallbacks = {
    show: function () {
      startListening();
      if (engine) syncWithPhotoshop();
    },
    hide: function () {
      stopListening();
    },
    destroy: function () {
      return teardown();
    }
  };
  try {
    if (GA.boot) GA.boot.setup(panelCallbacks);
    else if (uxp && uxp.entrypoints) uxp.entrypoints.setup({ panels: { glowAuraPanel: panelCallbacks } });
  } catch (e) {
    /* entrypoints may already be set up on reload */
  }

  try {
    boot();
    if (GA.boot) GA.boot.ok();
  } catch (e) {
    block("Glow Aura couldn't start", U.friendlyError(e));
  }

  GA.__debug = { state: state, getEngine: () => engine };
})();
